const projects={
aysen:{title:'Universidad de Aysén',headline:'Habitar el extremo.',place:'Coyhaique, Patagonia',type:'Educación / Proyecto',image:'aysen-2026-2-cover.webp',alt:'Visualización del proyecto Universidad de Aysén entre las montañas',sub:'Un lugar de encuentro en la Patagonia.',text:'El Edificio Fundacional de la Universidad de Aysén aborda la vida universitaria desde la relación con el paisaje y la tradición de construir espacios de encuentro y abrigo en el territorio austral.',status:'El proyecto cuenta con permiso de obra aprobado. La Universidad prevé realizar durante 2026 el llamado a licitación pública para la ejecución de la obra.',facts:[['Arquitectura','OF Arquitectos + MSRAA + Cavagnaro Rojo'],['Estado','Permiso de obra aprobado'],['Imagen','Visualizaciones del proyecto · 2026']],gallery:[['aysen-2026-4.webp','Corte perspectivado del conjunto'],['aysen-2026-1.webp','Organización espacial del edificio'],['aysen-2026-0.webp','Rectoría, tercer nivel'],['aysen-2026-3.webp','Laboratorios, segundo nivel'],['aysen-2026-5.webp','Laboratorios, tercer nivel']],next:'chagual',nextTitle:'Conjunto Chagual'},
chagual:{title:'Conjunto Chagual',headline:'Habitar frente al mar.',place:'Papudo, Región de Valparaíso',type:'Vivienda colectiva',image:'chagual.webp',alt:'Fachada y terrazas del conjunto residencial Conjunto Chagual',sub:'Vivienda y paisaje costero.',text:'El conjunto residencial Conjunto Chagual se sitúa en un terreno de suave pendiente hacia el norte, con vistas a la bahía de Papudo y próximo a Punta Pite. Las terrazas articulan la relación de las viviendas con el exterior.',facts:[['Arquitectura','OF Arquitectos + Más Fernández'],['Año del proyecto','2020'],['Superficie del terreno','14.000 m²'],['Superficie proyectada','16.340 m²'],['Fotografía','Areyh Kornfeld']],next:'nire',nextTitle:'Casa Ñire'},
nire:{title:'Casa Ñire',headline:'Una casa en el paisaje.',place:'Patagonia, Chile',type:'Vivienda',image:'nire-2.webp',alt:'Umbral rojo de Casa Ñire abierto hacia las montañas de la Patagonia',sub:'Entre el interior y el territorio.',text:'La madera, el color y las aperturas hacia el paisaje construyen la experiencia de habitar Casa Ñire. Una secuencia de interiores y umbrales vincula la vida cotidiana con el territorio patagónico.',facts:[['Estudio','OF Arquitectos'],['Programa','Vivienda'],['Lugar','Patagonia, Chile'],['Fotografía','Francisco Cepeda']],gallery:[['nire-3.webp','Madera y color en el recorrido interior'],['nire-1.webp','Cocina de madera en Casa Ñire']],next:'faad',nextTitle:'FAAD UDP'}
};
