const englishProjects={
aysen:{title:'Universidad de Aysén',headline:'Inhabiting the far south.',place:'Coyhaique, Patagonia',type:'Education / Project',image:'aysen-2026-2-cover.webp',alt:'Architectural visualisation of Universidad de Aysén with a mountain backdrop',sub:'A place to gather in Patagonia.',text:'The Foundational Building for Universidad de Aysén approaches university life through its relationship with the landscape and the local tradition of building spaces for gathering and shelter.',status:'The project has an approved building permit. The university plans to issue a public tender for construction during 2026.',facts:[['Architecture','OF Arquitectos + MSRAA + Cavagnaro Rojo'],['Status','Building permit approved'],['Image','Architectural visualisations · 2026']],gallery:[['aysen-2026-4.webp','Perspective section through the complex'],['aysen-2026-1.webp','Spatial organisation of the building'],['aysen-2026-0.webp','Rector’s office, third floor'],['aysen-2026-3.webp','Laboratories, second floor'],['aysen-2026-5.webp','Laboratories, third floor']],next:'chagual',nextTitle:'Conjunto Chagual'},
chagual:{title:'Conjunto Chagual',headline:'Living by the sea.',place:'Papudo, Valparaíso Region',type:'Collective housing',image:'chagual.webp',alt:'Façade and terraces of the Conjunto Chagual residential development',sub:'Housing and the coastal landscape.',text:'Conjunto Chagual occupies a gently north-sloping site with views over Papudo Bay, close to Punta Pite. The terraces shape the relationship between the homes and their surroundings.',facts:[['Architecture','OF Arquitectos + Más Fernández'],['Design year','2020'],['Site area','14,000 m²'],['Designed area','16,340 m²'],['Photography','Areyh Kornfeld']],next:'nire',nextTitle:'Casa Ñire'},
nire:{title:'Casa Ñire',headline:'A house in the landscape.',place:'Patagonia, Chile',type:'Private house',image:'nire-2.webp',alt:'Casa Ñire’s red threshold opening towards the Patagonian mountains',sub:'Between interior and landscape.',text:'Timber, colour and openings towards the landscape shape life at Casa Ñire. A sequence of interiors and thresholds connects everyday living with the Patagonian territory.',facts:[['Practice','OF Arquitectos'],['Programme','Private house'],['Location','Patagonia, Chile'],['Photography','Francisco Cepeda']],gallery:[['nire-3.webp','Timber and colour along the interior passage'],['nire-1.webp','Timber kitchen at Casa Ñire']],next:'faad',nextTitle:'FAAD UDP'}
};
Object.assign(projects,{"uoh": {"title": "Universidad de O’Higgins", "place": "Rengo, Chile", "image": "uoh0.webp", "next": "faad", "nextTitle": "FAAD UDP", "headline": "El patio como lugar común.", "type": "Educación / Proyecto", "sub": "Un campus para el encuentro.", "text": "La Facultad de Ingeniería del Campus Rengo se organiza alrededor de una secuencia de patios. Corredores y espacios intermedios reinterpretan la arquitectura del valle central, vinculando la vida universitaria con el clima y el paisaje. El conjunto permite desarrollar el programa por etapas.", "facts": [["Arquitectura", "Cavagnaro Rojo + MSRAA + OF Arquitectos"], ["Año del proyecto", "2022"], ["Programa", "Facultad de Ingeniería · Campus Rengo"], ["Imágenes", "Visualizaciones del proyecto"]], "alt": "Universidad de O’Higgins", "gallery": [["uoh1.webp", "Volumen del auditorio"], ["uoh2.webp", "Espacio de acceso al campus"]]}, "unab": {"title": "UNAB Viña del Mar", "place": "Viña del Mar, Chile", "image": "unab1.webp", "next": "faad", "nextTitle": "FAAD UDP", "headline": "Construir con la pendiente.", "type": "Educación / En obra", "sub": "La topografía como punto de partida.", "text": "En la Meseta del Gallo, el programa académico se distribuye en volúmenes aterrazados que siguen el relieve. Patios de luz y cubiertas habitables prolongan la vida universitaria al exterior y mantienen la relación con las vistas hacia la bahía.", "facts": [["Arquitectura", "MSRAA + OF Arquitectos"], ["Año del proyecto", "2024"], ["Superficie proyectada", "25.000 m²"], ["Imágenes", "Visualizaciones del proyecto"]], "alt": "UNAB Viña del Mar", "gallery": [["unab0.webp", "Volúmenes y vegetación del campus"], ["unab2.webp", "Fachadas del conjunto universitario"]]}, "mallarauco": {"title": "Casa Mallarauco", "place": "Mallarauco, Chile", "image": "mallarauco0.webp", "next": "faad", "nextTitle": "FAAD UDP", "headline": "Entre las secuoyas.", "type": "Vivienda", "sub": "Una casa que conserva el bosque.", "text": "El programa se distribuye en pabellones para conservar las secuoyas existentes. Una pasarela exterior enlaza las piezas entre los árboles. La construcción prefabricada en madera reduce la intervención en el terreno, mientras el revestimiento oscuro integra la casa en la sombra del bosque.", "facts": [["Arquitectura", "Francisco Cepeda + Álvaro Ramírez"], ["Año del proyecto", "2016"], ["Superficie proyectada", "550 m²"], ["Fotografía", "Pablo Casals"]], "alt": "Casa Mallarauco", "gallery": [["mallarauco2.webp", "La pasarela entre los pabellones"], ["mallarauco1.webp", "Luz interior al caer la noche"]]}, "pullay": {"title": "Casa Pullay", "place": "Trehualemu, Pelluhue, Chile", "image": "pullay1.webp", "next": "faad", "nextTitle": "FAAD UDP", "headline": "Entre el bosque y el mar.", "type": "Vivienda", "sub": "Un refugio frente al Pacífico.", "text": "Dos alas forman un exterior protegido del viento y abren la casa al mar y al bosque. La estructura de madera laminada y el perfil curvo de la cubierta evocan la carpintería de ribera. Su modulación permite una construcción parcialmente prefabricada.", "facts": [["Arquitectura", "Álvaro Ramírez + Francisco Cepeda"], ["Año del proyecto", "2023"], ["Superficie proyectada", "300 m²"], ["Fotografía", "Marcos Zegers"]], "alt": "Casa Pullay", "gallery": [["pullay2.webp", "Perfil curvo de la cubierta y envolvente exterior"]]}, "museo": {"title": "Museo de la Memoria y DD. HH. del Biobío", "place": "Concepción, Chile", "image": "museo-editorial-0.webp", "next": "faad", "nextTitle": "FAAD UDP", "headline": "Un lugar para la memoria.", "type": "Cultura / Entregado", "sub": "Memoria y espacio público.", "text": "Propuesta para el Museo de la Memoria y los Derechos Humanos de la Región del Biobío, en Concepción. El equipo obtuvo el primer lugar del concurso y entregó el proyecto; su construcción no se ha iniciado.", "facts": [["Arquitectura", "MCRJAG + OF Arquitectos"], ["Año", "2018"], ["Concurso", "Primer lugar"], ["Estado", "No construido"], ["Imágenes", "Visualización del concurso"]], "alt": "Visualización del Museo de la Memoria y DD. HH. del Biobío"}});
Object.assign(englishProjects,{"uoh": {"title": "Universidad de O’Higgins", "place": "Rengo, Chile", "image": "uoh0.webp", "next": "faad", "nextTitle": "FAAD UDP", "headline": "The courtyard as common ground.", "type": "Education / Project", "sub": "A campus for exchange.", "text": "Courtyards form the organising principle for the Faculty of Engineering at Campus Rengo. Covered walkways reinterpret the architecture of Chile’s Central Valley, connecting academic life with its climate and landscape. The campus is designed to grow in phases.", "facts": [["Architecture", "Cavagnaro Rojo + MSRAA + OF Arquitectos"], ["Design year", "2022"], ["Programme", "Faculty of Engineering · Campus Rengo"], ["Images", "Architectural visualisations"]], "alt": "Universidad de O’Higgins", "gallery": [["uoh1.webp", "Auditorium volume"], ["uoh2.webp", "Campus entrance space"]]}, "unab": {"title": "UNAB Viña del Mar", "place": "Viña del Mar, Chile", "image": "unab1.webp", "next": "faad", "nextTitle": "FAAD UDP", "headline": "Building with the slope.", "type": "Education / Under construction", "sub": "Topography as a starting point.", "text": "On Meseta del Gallo, terraced volumes follow the terrain. Light wells and roof terraces extend university life outdoors, while maintaining views towards the bay.", "facts": [["Architecture", "MSRAA + OF Arquitectos"], ["Design year", "2024"], ["Designed area", "25,000 m²"], ["Images", "Architectural visualisations"]], "alt": "UNAB Viña del Mar", "gallery": [["unab0.webp", "Campus volumes and planting"], ["unab2.webp", "University façades"]]}, "mallarauco": {"title": "Casa Mallarauco", "place": "Mallarauco, Chile", "image": "mallarauco0.webp", "next": "faad", "nextTitle": "FAAD UDP", "headline": "Among the redwoods.", "type": "Private house", "sub": "A house that preserves the woodland.", "text": "Separate pavilions preserve the existing redwoods, linked by an outdoor walkway through the trees. Prefabricated timber construction reduces disturbance to the site, while dark cladding settles the house into the woodland shade.", "facts": [["Architecture", "Francisco Cepeda + Álvaro Ramírez"], ["Design year", "2016"], ["Designed area", "550 m²"], ["Photography", "Pablo Casals"]], "alt": "Casa Mallarauco", "gallery": [["mallarauco2.webp", "The walkway between pavilions"], ["mallarauco1.webp", "Interior light at nightfall"]]}, "pullay": {"title": "Casa Pullay", "place": "Trehualemu, Pelluhue, Chile", "image": "pullay1.webp", "next": "faad", "nextTitle": "FAAD UDP", "headline": "Between woodland and ocean.", "type": "Private house", "sub": "A shelter facing the Pacific.", "text": "Two wings shelter an outdoor space from the wind and open the house towards the ocean and woodland. Glulam framing and a curved roof profile recall the local boatbuilding tradition. A repeated structural module supports partial prefabrication.", "facts": [["Architecture", "Álvaro Ramírez + Francisco Cepeda"], ["Design year", "2023"], ["Designed area", "300 m²"], ["Photography", "Marcos Zegers"]], "alt": "Casa Pullay", "gallery": [["pullay2.webp", "Curved roof profile and exterior envelope"]]}, "museo": {"title": "Museo de la Memoria y DD. HH. del Biobío", "place": "Concepción, Chile", "image": "museo-editorial-0.webp", "next": "faad", "nextTitle": "FAAD UDP", "headline": "A place for memory.", "type": "Culture / Delivered", "sub": "Memory and public space.", "text": "A proposal for the Museum of Memory and Human Rights of the Biobío Region, in Concepción. The team was awarded first prize in the competition and delivered the project; construction has not begun.", "facts": [["Architecture", "MCRJAG + OF Arquitectos"], ["Year", "2018"], ["Competition", "First prize"], ["Status", "Unbuilt"], ["Images", "Competition visualisation"]], "alt": "Visualisation of the Museo de la Memoria y DD. HH. del Biobío"}});
Object.assign(projects.nire,{"headline": "Habitar la Patagonia.", "place": "Puerto Guadal, lago General Carrera, Aysén", "type": "Vivienda / Obra construida", "image": "nire-exterior.webp", "alt": "Casa Ñire: cubierta roja, estructura esbelta y podio de hormigón sobre la ladera", "sub": "Una casa que encuentra su lugar.", "text": "Frente a Bahía Catalina, Casa Ñire se apoya en una roca y abre sus espacios al lago General Carrera. Un podio de hormigón, una estructura ligera y una cubierta inclinada construyen un refugio donde la escala doméstica convive con la amplitud del paisaje.", "facts": [["Arquitectura", "Francisco Cepeda · OF Arquitectos"], ["Proyecto / Construcción", "2024 / 2025"], ["Superficie construida", "110 m²"], ["Construcción", "OF Construcción SpA"], ["Cálculo estructural", "Alex Popp"], ["Fotografía", "Francisco Cepeda"]], "chapters": [["Fundar sobre la roca.", "El emplazamiento se ajustó durante el proyecto para encontrar un apoyo en la roca existente. El podio de hormigón prolonga esa base y permite acercar la casa al borde. Desde el estar, el terreno desaparece de la vista y el lago ocupa el horizonte.", [["living", "El estar se abre al lago bajo la cubierta roja."]]], ["Una planta pensada en corte.", "El acceso y los dormitorios se sitúan medio metro por encima del estar, el comedor y la cocina. Tres gradas conectan ambos niveles. Un mueble longitudinal reúne equipamiento y servicios, separa las áreas de la casa y deja pasar la luz por encima de las divisiones.", [["kitchen", "Cocina, comedor y estar forman un espacio continuo."]]], ["La cubierta y el paisaje.", "La pendiente de la cubierta acompaña la topografía hacia el lago. Desde la compresión del acceso, la altura y las vistas cambian a lo largo del recorrido. En los dormitorios, las aperturas mantienen el vínculo con el paisaje; en el estar, la madera del mobiliario recoge el cuerpo frente a la extensión del agua.", [["bedroom", "El dormitorio participa de la misma relación entre abrigo y paisaje."]]], ["Color, materia y refugio.", "El rojo tinto recoge los colores de galpones y embarcaciones del sur. Se aproxima al follaje otoñal del ñire y contrasta con la nieve en invierno. La estructura de acero y el podio de hormigón se complementan con mobiliario de lenga, concebido como parte de la arquitectura.", [["material", "El revestimiento rojo y la vegetación junto a la casa."], ["dusk", "Al caer la tarde, la luz interior revela el refugio sobre el lago."]]]]});
Object.assign(englishProjects.nire,{"headline": "Inhabiting Patagonia.", "place": "Puerto Guadal, General Carrera Lake, Aysén", "type": "Private house / Built", "image": "nire-exterior.webp", "alt": "Casa Ñire: red roof, slender structure and concrete podium on the hillside", "sub": "A house that finds its place.", "text": "Facing Bahía Catalina, Casa Ñire rests on rock and opens its rooms to General Carrera Lake. A concrete podium, a light structure and a sloping roof create a shelter where domestic scale meets an expansive landscape.", "facts": [["Architecture", "Francisco Cepeda · OF Arquitectos"], ["Design / Construction", "2024 / 2025"], ["Built area", "110 m²"], ["Contractor", "OF Construcción SpA"], ["Structural engineering", "Alex Popp"], ["Photography", "Francisco Cepeda"]], "chapters": [["Founded on rock.", "The position of the house shifted during design to find support on existing rock. The concrete podium extends this foundation, allowing the house to approach the edge. From the living room, the ground disappears from view and the lake fills the horizon.", [["living", "The living room opens to the lake beneath the red roof."]]], ["A plan conceived in section.", "The entrance and bedrooms sit half a metre above the living room, dining room and kitchen. Three steps connect the two levels. A long central cabinet gathers equipment and services, separates the rooms and lets daylight pass above the partitions.", [["kitchen", "Kitchen, dining and living spaces form a continuous room."]]], ["The roof and the landscape.", "The roof slopes towards the lake, following the topography. From the compressed entrance, ceiling heights and views change along the route. Bedroom openings maintain the connection to the landscape, while timber furniture shelters the body in the living room, facing the open water.", [["bedroom", "The bedroom shares the same balance of shelter and landscape."]]], ["Colour, material and shelter.", "The deep red recalls the sheds and boats of southern Chile. It echoes the autumn foliage of the ñire and contrasts with winter snow. Steel framing and the concrete podium are complemented by lenga furniture, conceived as part of the architecture.", [["material", "Red cladding and vegetation beside the house."], ["dusk", "At dusk, interior light reveals the shelter above the lake."]]]]});
delete projects.nire.gallery;delete englishProjects.nire.gallery;
/* Project narratives adapted from the office archive. */
Object.assign(projects,{"camino": {"title": "Casa Camino el Alto", "place": "El Arrayán, Lo Barnechea, Santiago", "headline": "Una casa en la pendiente.", "sub": "Dos niveles, dos formas de habitar.", "text": "La casa ocupa una ladera sobre el valle de Santiago. La planta baja se abre al terreno y las vistas; arriba, los dormitorios se reúnen en un volumen de madera con terrazas que dan privacidad sin perder la relación con la montaña.", "facts": [["Arquitectura", "Francisco Cepeda + Álvaro Ramírez"], ["Proyecto / Construcción", "2011 / 2013–2014"], ["Superficie construida", "200 m²"], ["Construcción", "IDEC"], ["Cálculo estructural", "Alex Popp"], ["Fotografía", "Cristóbal Palma"]], "chapters": [["Construir con el terreno.", "Un solo corte longitudinal permite apoyar la casa en la ladera y limitar los movimientos de tierra. El volumen superior se extiende sobre la planta baja, haciendo visible la diferencia entre las áreas comunes y los recintos privados.", [["editorial-1", "El volumen de madera se proyecta sobre la ladera."]]], ["La planta baja se abre.", "Los muros de hormigón contienen el terreno por un lado; por el otro, los ventanales vinculan estar y comedor con el exterior. La continuidad del espacio aprovecha las vistas hacia la cordillera y el valle.", [["editorial-2", "El espacio común se prolonga hacia el jardín."]]], ["Terrazas entre los dormitorios.", "El nivel superior se construye en madera. Sus terrazas intermedias permiten abrir las habitaciones al paisaje y mantener espacios exteriores más recogidos.", [["editorial-3", "Una terraza entre los volúmenes del nivel superior."], ["editorial-4", "La escalera conecta los dos niveles de la casa."], ["editorial-5", "La montaña desde una de las terrazas."]]]], "image": "camino-editorial-0.webp", "alt": "Casa Camino el Alto · Una casa en la pendiente", "type": "Vivienda / Obra construida", "next": "ensignia", "nextTitle": "Casa Ensignia Gerber"}, "ensignia": {"title": "Casa Ensignia Gerber", "place": "Tunquén, Región de Valparaíso", "headline": "Abrirse al mar.", "sub": "Una envolvente, dos áreas.", "text": "La casa reúne el programa principal y los dormitorios de invitados bajo una envolvente continua. Hacia la calle se cierra con pizarra; hacia el océano se abre con vidrio y terrazas. Entre ambas áreas, un exterior cubierto ofrece protección del viento.", "facts": [["Arquitectura", "Francisco Cepeda + Álvaro Ramírez"], ["Colaborador", "Nicolás Cabargas"], ["Proyecto / Construcción", "2010 / 2011–2012"], ["Superficie construida", "140 m²"], ["Cálculo estructural", "Alex Popp"], ["Fotografía", "Marcos Mendizabal"]], "chapters": [["Una cara protegida.", "Los pliegues de cubierta y fachada forman una envolvente revestida en pizarra negra. Hacia el acceso, las aberturas son puntuales: la casa protege su interior de la calle y de las condiciones del lugar.", [["editorial-1", "La pizarra continúa entre cubierta y fachada."], ["editorial-2", "Patio de luz en la envolvente hacia la calle."]]], ["Una terraza entre dos áreas.", "El área principal acompaña las cotas del terreno. El volumen de invitados cambia de dirección para buscar las vistas hacia el norte. Una terraza techada vincula ambos y resguarda del surazo.", [["editorial-3", "La terraza cubierta articula los espacios de la casa."]]], ["Habitar hacia el horizonte.", "Hacia el norte y el poniente, los ventanales abren los recintos al mar. Los aleros y la madera acompañan esta transición entre el interior y las terrazas.", [["editorial-4", "Galería exterior y vistas al océano."], ["editorial-5", "La apertura del interior al caer la tarde."]]]], "image": "ensignia-editorial-0.webp", "alt": "Casa Ensignia Gerber · Abrirse al mar", "type": "Vivienda / Obra construida", "next": "pullay", "nextTitle": "Casa Pullay"}, "chagual": {"title": "Conjunto Chagual", "place": "Papudo, Región de Valparaíso", "headline": "Vivienda junto al mar.", "sub": "El conjunto y sus espacios intermedios.", "text": "Conjunto Chagual reúne viviendas colectivas en Papudo. Las terrazas, las circulaciones exteriores y los espacios de acceso dan espesor a sus fachadas y relacionan la escala del edificio con la llegada a cada vivienda.", "facts": [["Arquitectura", "OF Arquitectos + Más Fernández"], ["Inmobiliaria", "Patagon Land"], ["Programa", "Vivienda colectiva"], ["Lugar", "Papudo, Chile"], ["Fotografía", "Areyh Kornfeld"]], "chapters": [["La escala del conjunto.", "Las vistas generales muestran la disposición de los bloques y su relación con el suelo. La repetición de niveles convive con una fachada que cambia según las terrazas y las circulaciones.", [["editorial-1", "Vista general del conjunto desde la calle."]]], ["Llegar a las viviendas.", "Los accesos se reconocen por los cambios de nivel, los muros y las pasarelas. Estos espacios exteriores forman parte del recorrido cotidiano entre la calle y las viviendas.", [["editorial-2", "El acceso entre los edificios."], ["editorial-3", "La pasarela aproxima al edificio."]]], ["Terrazas y circulación.", "Las escaleras exteriores dibujan diagonales sobre la fachada. En otros frentes, los antepechos y las divisiones de las terrazas construyen un ritmo horizontal y ofrecen distintos grados de resguardo.", [["editorial-4", "Las escaleras exteriores en la fachada."], ["editorial-5", "Terrazas y divisiones del frente residencial."]]]], "image": "chagual-editorial-0.webp", "alt": "Conjunto Chagual · Vivienda junto al mar", "type": "Vivienda colectiva / Obra construida", "next": "nire", "nextTitle": "Casa Ñire"}, "pullay": {"title": "Casa Pullay", "place": "Trehualemu, Pelluhue, Chile", "headline": "Entre el bosque y el mar.", "sub": "Un patio protegido frente al Pacífico.", "text": "La casa se sitúa en el borde entre un pequeño bosque y la costa de Trehualemu. Dos pabellones forman una L: uno acompaña el mar y el otro se extiende hacia el interior del terreno. Entre ambos queda un espacio exterior protegido del viento.", "facts": [["Arquitectura", "Álvaro Ramírez + Francisco Cepeda"], ["Programa", "Vivienda de vacaciones"], ["Estructura", "Madera laminada"], ["Fotografía", "Marcos Zegers"]], "chapters": [["Situarse en el borde.", "El pabellón principal se dispone paralelo a la costa, con vistas al océano y al bosque. El ala perpendicular reúne servicios y dormitorio de invitados y ayuda a resguardar el exterior del surazo.", [["editorial-1", "La casa entre el bosque y la costa."]]], ["El patio como espacio común.", "Una terraza parcialmente cubierta y el quincho relacionan las dos alas. Las aperturas permiten que la vida de la casa se extienda hacia este espacio exterior protegido.", [["editorial-2", "El patio y el frente abierto de la casa."]]], ["La madera y la cubierta.", "Una estructura de madera laminada mecanizada repite sus módulos para facilitar el montaje. La curvatura de la cubierta amplía el espacio interior y recoge una referencia a la carpintería de ribera de la zona.", [["editorial-3", "La estructura de madera define el espacio común."], ["editorial-4", "La repetición estructural acompaña el recorrido interior."]]], ["Cerrar y abrir.", "Los extremos norte y sur se revisten con tablas de pino pintadas de negro. Los frentes oriente y poniente se abren hacia el bosque y el mar, haciendo visible el contraste entre protección y transparencia.", [["editorial-5", "El perfil curvo y la envolvente exterior al atardecer."]]]], "image": "pullay-editorial-0.webp", "alt": "Casa Pullay · Entre el bosque y el mar", "type": "Vivienda / Obra construida", "next": "chagual", "nextTitle": "Conjunto Chagual"}});
Object.assign(englishProjects,{"camino": {"title": "Casa Camino el Alto", "place": "El Arrayán, Lo Barnechea, Santiago", "headline": "A house on the hillside.", "sub": "Two levels, two ways of living.", "text": "The house occupies a slope above Santiago’s valley. The ground floor opens to the land and views; above, bedrooms sit within a timber volume with terraces that offer privacy and a connection to the mountains.", "facts": [["Architecture", "Francisco Cepeda + Álvaro Ramírez"], ["Design / Construction", "2011 / 2013–2014"], ["Built area", "200 m²"], ["Contractor", "IDEC"], ["Structural engineering", "Alex Popp"], ["Photography", "Cristóbal Palma"]], "chapters": [["Building with the terrain.", "A single longitudinal cut supports the house on the slope and limits earthworks. The upper volume extends over the ground floor, expressing the distinction between shared and private rooms.", [["editorial-1", "The timber volume projects over the hillside."]]], ["An open ground floor.", "Concrete walls retain the hillside on one side; on the other, glazing connects living and dining spaces to the outdoors. The continuous room opens towards the mountains and valley.", [["editorial-2", "The shared space extends towards the garden."]]], ["Terraces between bedrooms.", "The upper level is built in timber. Intermediate terraces open the bedrooms to the landscape while creating more sheltered outdoor spaces.", [["editorial-3", "A terrace between the upper volumes."], ["editorial-4", "The staircase connects the two floors."], ["editorial-5", "Mountain views from an upper terrace."]]]], "image": "camino-editorial-0.webp", "alt": "Casa Camino el Alto · A house on the hillside", "type": "Private house / Built", "next": "ensignia", "nextTitle": "Casa Ensignia Gerber"}, "ensignia": {"title": "Casa Ensignia Gerber", "place": "Tunquén, Valparaíso Region", "headline": "Opening to the sea.", "sub": "One envelope, two areas.", "text": "The house brings the main rooms and guest bedrooms together under a continuous envelope. Slate encloses the street side; glazing and terraces open towards the ocean. A covered outdoor space between the two areas provides shelter from the wind.", "facts": [["Architecture", "Francisco Cepeda + Álvaro Ramírez"], ["Collaborator", "Nicolás Cabargas"], ["Design / Construction", "2010 / 2011–2012"], ["Built area", "140 m²"], ["Structural engineering", "Alex Popp"], ["Photography", "Marcos Mendizabal"]], "chapters": [["A sheltered face.", "Folds in the roof and façade form an envelope clad in black slate. Openings towards the entrance are limited, protecting the interior from the street and weather.", [["editorial-1", "Slate continues across roof and façade."], ["editorial-2", "A lightwell within the street-facing envelope."]]], ["A terrace between two areas.", "The main rooms follow the contours. The guest wing changes direction to seek northern views. A covered terrace connects them and shelters against the cold southwesterly wind.", [["editorial-3", "The covered terrace connects the two parts of the house."]]], ["Living towards the horizon.", "Glazing opens the rooms to the sea on the north and west. Eaves and timber frame the transition between rooms and terraces.", [["editorial-4", "The outdoor gallery and ocean views."], ["editorial-5", "The interior opens to the landscape at dusk."]]]], "image": "ensignia-editorial-0.webp", "alt": "Casa Ensignia Gerber · Opening to the sea", "type": "Private house / Built", "next": "pullay", "nextTitle": "Casa Pullay"}, "chagual": {"title": "Conjunto Chagual", "place": "Papudo, Valparaíso Region", "headline": "Housing by the sea.", "sub": "The ensemble and its shared thresholds.", "text": "Conjunto Chagual brings together collective housing in Papudo. Terraces, outdoor circulation and entrances give depth to the façades and connect the scale of the buildings with the approach to each home.", "facts": [["Architecture", "OF Arquitectos + Más Fernández"], ["Developer", "Patagon Land"], ["Programme", "Collective housing"], ["Location", "Papudo, Chile"], ["Photography", "Areyh Kornfeld"]], "chapters": [["The scale of the ensemble.", "Overall views show how the blocks sit on the ground. Repeated floors meet façades shaped by terraces and circulation.", [["editorial-1", "The ensemble viewed from the street."]]], ["Approaching the homes.", "Changes in level, walls and walkways define the entrances. These outdoor spaces form part of the daily route between the street and the homes.", [["editorial-2", "An entrance between the buildings."], ["editorial-3", "A walkway approaching the building."]]], ["Terraces and circulation.", "Outdoor stairs trace diagonals across the façade. Elsewhere, parapets and terrace partitions establish a horizontal rhythm and different degrees of shelter.", [["editorial-4", "Outdoor stairs on the façade."], ["editorial-5", "Terraces and partitions on the residential elevation."]]]], "image": "chagual-editorial-0.webp", "alt": "Conjunto Chagual · Housing by the sea", "type": "Collective housing / Built", "next": "nire", "nextTitle": "Casa Ñire"}, "pullay": {"title": "Casa Pullay", "place": "Trehualemu, Pelluhue, Chile", "headline": "Between woodland and ocean.", "sub": "A sheltered courtyard facing the Pacific.", "text": "The house sits at the edge of woodland on the coast of Trehualemu. Two pavilions form an L: one follows the sea, while the other extends inland. Between them lies an outdoor space protected from the wind.", "facts": [["Architecture", "Álvaro Ramírez + Francisco Cepeda"], ["Programme", "Holiday house"], ["Structure", "Glued laminated timber"], ["Photography", "Marcos Zegers"]], "chapters": [["Building at the edge.", "The main pavilion runs parallel to the coast, facing both ocean and woodland. The perpendicular wing contains services and a guest bedroom and helps shelter the outdoors from southwesterly winds.", [["editorial-1", "The house between woodland and coast."]]], ["A shared courtyard.", "A partly covered terrace and barbecue area connect the two wings. Openings extend everyday life into this sheltered outdoor space.", [["editorial-2", "The courtyard and the open façade."]]], ["Timber and roof.", "A machined glulam structure repeats its modules to simplify assembly. The curved roof opens up the interior and recalls the area’s boatbuilding tradition.", [["editorial-3", "The timber structure defines the shared room."], ["editorial-4", "Repeated structural elements along the interior passage."]]], ["Enclosure and openness.", "The north and south ends are clad in black-painted pine boards. East and west façades open to woodland and ocean, expressing the contrast between shelter and transparency.", [["editorial-5", "The curved profile and outer envelope at dusk."]]]], "image": "pullay-editorial-0.webp", "alt": "Casa Pullay · Between woodland and ocean", "type": "Private house / Built", "next": "chagual", "nextTitle": "Conjunto Chagual"}});
projects.buchupureo={"title": "Casa Buchupureo", "headline": "Una casa sobre la pendiente.", "place": "Buchupureo, Chile", "type": "Vivienda / Obra construida", "image": "buchupureo-editorial-0.webp", "alt": "Casa Buchupureo entre los árboles, con cubierta de piedra laja frente al océano", "sub": "Dos recintos y una terraza.", "text": "Esta casa de 55 m² se apoya sobre pilotes en una ladera abrupta frente al Pacífico. Un dormitorio con baño y un estar con cocina se relacionan a través de una terraza central. La madera y la piedra laja vinculan la construcción con los materiales de la zona.", "facts": [["Arquitectura", "Álvaro Ramírez + Clarisa Elton"], ["Proyecto / Construcción", "2006 / 2006"], ["Superficie construida", "55 m²"], ["Construcción", "Ruperto Vera"], ["Fotografía", "Álvaro Ramírez + Clarisa Elton"]], "chapters": [["Apoyarse en la ladera.", "Los pilotes reducen la intervención sobre el suelo y permiten el paso del agua bajo la casa. La estructura de madera queda a la vista y establece la relación entre los recintos y la pendiente.", [["editorial-1", "La casa vista desde el borde rocoso."]]], ["Una terraza entre los recintos.", "La terraza central funciona como llegada y como espacio de encuentro entre el dormitorio y el estar con cocina. Protegida del viento, permite permanecer al exterior con una vista abierta al océano.", [["editorial-2", "El dormitorio se abre hacia la terraza y el mar."], ["editorial-3", "El espacio de estar y comedor frente al Pacífico."]]], ["Madera y piedra laja.", "La casa utiliza pino insigne en estructura y revestimientos. La cubierta de madera se pliega ligeramente y se separa de los muros para dejar entrar luz. Sobre ella, la piedra laja protege el techo y recoge una materialidad presente en las construcciones locales.", [["editorial-4", "La piedra laja de la cubierta y el horizonte del mar."]]]], "next": "ensignia", "nextTitle": "Casa Ensignia Gerber"};
englishProjects.buchupureo={"title": "Casa Buchupureo", "headline": "A house above the slope.", "place": "Buchupureo, Chile", "type": "Private house / Built", "image": "buchupureo-editorial-0.webp", "alt": "Casa Buchupureo among trees, with a stone-covered roof facing the ocean", "sub": "Two rooms and a terrace.", "text": "This 55 m² house rests on posts on a steep slope facing the Pacific. A bedroom with bathroom and a living room with kitchen are connected by a central terrace. Timber and laja stone relate the building to local materials.", "facts": [["Architecture", "Álvaro Ramírez + Clarisa Elton"], ["Design / Construction", "2006 / 2006"], ["Built area", "55 m²"], ["Contractor", "Ruperto Vera"], ["Photography", "Álvaro Ramírez + Clarisa Elton"]], "chapters": [["Resting on the hillside.", "Posts reduce disturbance to the ground and allow water to flow beneath the house. The exposed timber structure connects the rooms to the slope.", [["editorial-1", "The house seen from the rocky edge."]]], ["A terrace between the rooms.", "The central terrace serves as both arrival space and a shared threshold between the bedroom and the living room with kitchen. Sheltered from the wind, it provides an outdoor place with open ocean views.", [["editorial-2", "The bedroom opens towards the terrace and sea."], ["editorial-3", "Living and dining space facing the Pacific."]]], ["Timber and laja stone.", "Radiata pine is used for both structure and cladding. The gently folded timber roof separates from the walls to admit daylight. Laja stone protects its surface, drawing on a material found in local buildings.", [["editorial-4", "The stone roof and the sea horizon."]]]], "next": "ensignia", "nextTitle": "Casa Ensignia Gerber"};
projects.buin={"title": "Casa Buin", "headline": "Una casa entre el patio y el jardín.", "place": "Buin, Chile", "type": "Vivienda / Obra construida", "image": "buin-editorial-0.webp", "alt": "Casa Buin vista desde el jardín, con galería y fachada acristalada", "sub": "Una casa de dos caras.", "text": "La Casa Buin, también conocida como Casa Errázuriz Cooper, se organiza entre un frente revestido en madera y una fachada abierta al jardín. Una galería longitudinal acompaña los recintos y vincula el interior con el exterior.", "facts": [["Arquitectura", "OF Arquitectos + Paula Velasco + Alberto Moletto"], ["Año", "2011"], ["Fotografía", "Nico Saieh"]], "chapters": [["Dos frentes.", "Hacia el acceso, el revestimiento de madera construye una fachada más cerrada. Hacia el jardín, la casa se abre mediante una secuencia de ventanas y puertas de vidrio.", [["editorial-1", "El volumen y su apertura hacia el jardín."], ["editorial-2", "El frente de madera y el acceso."]]], ["Luz y recorrido.", "La galería y los espacios interiores reciben luz natural a lo largo de la casa. La cubierta y el revestimiento de madera dan continuidad al recorrido.", [["editorial-3", "El espacio interior y la galería."], ["editorial-4", "La luz sobre la cubierta de madera."]]], ["Patio y árboles.", "Los árboles existentes acompañan la llegada y enmarcan la relación de la vivienda con el terreno.", [["editorial-5", "El patio bajo la sombra de los árboles."]]]], "next": "buchupureo", "nextTitle": "Casa Buchupureo"};
englishProjects.buin={"title": "Casa Buin", "headline": "A house between courtyard and garden.", "place": "Buin, Chile", "type": "Private house / Built", "image": "buin-editorial-0.webp", "alt": "Casa Buin seen from the garden, with its glazed façade", "sub": "A house with two sides.", "text": "Casa Buin, also known as Casa Errázuriz Cooper, is arranged between a timber-clad entrance front and an open garden façade. A long gallery accompanies the rooms and connects inside and outside.", "facts": [["Architecture", "OF Arquitectos + Paula Velasco + Alberto Moletto"], ["Year", "2011"], ["Photography", "Nico Saieh"]], "chapters": [["Two fronts.", "Timber cladding forms a more enclosed face towards the entrance. The garden side opens through a sequence of glass doors and windows.", [["editorial-1", "The volume opening towards the garden."], ["editorial-2", "The timber-clad entrance front."]]], ["Light and movement.", "Natural light reaches the gallery and interior rooms along the house. Timber roof and cladding give continuity to the route.", [["editorial-3", "Interior space and gallery."], ["editorial-4", "Light across the timber roof."]]], ["Courtyard and trees.", "Existing trees mark the approach and frame the relationship between house and site.", [["editorial-5", "Courtyard beneath the trees."]]]], "next": "buchupureo", "nextTitle": "Casa Buchupureo"};


// Fichas incorporadas desde Cargo Collective (sep 2026)
Object.assign(projects,{"lavandulas": {"title": "Casa Lavándulas", "headline": "Una casa abierta al jardín.", "place": "Las Condes, Santiago", "type": "Vivienda / Obra construida", "image": "lavandulas-editorial-0.webp", "alt": "Casa Lavándulas vista desde el jardín, con su alero blanco continuo", "sub": "Una casa en un terreno arbolado.", "text": "Remodelación de una casa de un piso en Las Condes, en un terreno de 1.600 m² con árboles existentes. El proyecto reorganiza 250 m² construidos en torno al jardín y a una secuencia de terrazas.", "facts": [["Arquitectura", "OF Arquitectos"], ["Proyecto", "2010"], ["Construcción", "2011"], ["Superficie", "250 m²"], ["Cálculo", "Alex Popp"], ["Construcción", "RCubo"], ["Fotografía", "Francisco Cepeda"]], "chapters": [["La casa y el jardín.", "Un alero blanco continuo ordena la fachada hacia el jardín y protege las terrazas. Los árboles existentes se mantienen como parte del proyecto.", [["editorial-1", "Fachada hacia el jardín entre los árboles existentes."], ["editorial-2", "El alero y la terraza."]]], ["Pérgola y patio.", "Una pérgola de madera filtra la luz sobre la terraza. El acceso se resuelve a través de un patio ajardinado.", [["editorial-3", "Terraza bajo la pérgola de madera."], ["editorial-4", "Patio de acceso."]]], ["Interior.", "Madera y superficies blancas dan continuidad a los recintos, abiertos hacia el exterior.", [["editorial-5", "Cocina."], ["editorial-6", "Comedor abierto al patio."]]]], "next": "yunis", "nextTitle": "Casa Yunis-Alcántara"}, "estadio": {"title": "Gimnasio Estadio Español", "headline": "Un lugar de encuentro para el deporte.", "place": "Las Condes, Santiago", "type": "Deporte / Proyecto", "image": "estadio-editorial-0.webp", "alt": "Fachada del gimnasio del Estadio Español", "sub": "Reunir programas dispersos.", "text": "Los deportes del sector funcionaban desvinculados entre sí. El proyecto reúne gimnasio, gimnasia artística, spa, oficinas, camarines y salas múltiples, y define el acceso principal a los edificios vecinos. Su proporción sigue a los edificios contiguos y su materialidad blanca evita competir con ellos.", "facts": [["Arquitectura", "OF Arquitectos + Pasiva"], ["Concurso", "Primer lugar, 2010"], ["Año", "2014"], ["Superficie", "6.500 m²"], ["Imágenes", "Visualizaciones del proyecto"]], "chapters": [["Un acceso común.", "El edificio ordena los recorridos del recinto: desde el trinquete y el básquetbol, al oriente, hasta la piscina techada, al poniente.", [["editorial-1", "Acceso y patio."], ["editorial-2", "Hall de acceso."]]], ["Transparencia.", "Los recintos se comunican visualmente entre sí. Esto permite acoger distintas actividades y favorece el encuentro entre socios.", [["editorial-3", "Cancha y circulaciones."], ["editorial-4", "Sala de máquinas."]]], ["Gimnasia y spa.", "La gimnasia artística y el spa completan un programa que se recorre como una secuencia continua.", [["editorial-5", "Gimnasia artística."], ["editorial-6", "Spa."]]]], "next": "fg", "nextTitle": "Casa FG"}, "fee": {"title": "Facultad de Economía y Empresa UDP", "headline": "Dos edificios y un lugar de encuentro.", "place": "Huechuraba, Santiago", "type": "Educación / Concurso", "image": "fee-editorial-0.webp", "alt": "Visualización de la Facultad de Economía y Empresa UDP desde la avenida", "sub": "Una propuesta de campus.", "text": "El encargo se resuelve en dos edificios comunicados, de pregrado y postgrado. Bajo ellos, una placa de dos niveles subterráneos reúne el programa común. Una pasarela metálica preparada para recibir vegetación conecta ambos edificios y activa el espacio entre ellos como lugar de encuentro.", "facts": [["Arquitectura", "Álvaro Ramírez, Francisco Cepeda, C. Briones"], ["Concurso", "Segundo lugar"], ["Año", "2010"], ["Superficie", "15.000 m²"], ["Imágenes", "Visualizaciones del concurso"]], "chapters": [["Entre dos edificios.", "La pasarela funciona como conexión de uso y como orden general del campus. El vacío entre edificios se convierte en el principal lugar de reunión.", [["editorial-1", "Terraza bajo la pasarela."], ["editorial-2", "Acceso y plaza."]]], ["Estrategia energética.", "El programa se ubica según su carga de uso: el intensivo, enterrado; el continuo, protegido y con vistas; el esporádico, hacia el paseo. Ventilación natural, fachadas específicas, barreras verdes y geotermia completan la estrategia.", [["editorial-3", "Espacio entre edificios."], ["editorial-4", "Llegada al edificio."]]], ["El campus.", "La propuesta plantea un criterio para los futuros edificios del campus.", [["editorial-5", "Vista general del conjunto."]]]], "next": "unabconce", "nextTitle": "UNAB Concepción"}, "aguadelpalo": {"title": "Casa Agua del Palo", "headline": "Ampliar sin que se note.", "place": "Vitacura, Santiago", "type": "Vivienda / Obra construida", "image": "aguadelpalo-editorial-0.webp", "alt": "Casa Agua del Palo al atardecer desde la calle", "sub": "Una casa de Christian de Groote.", "text": "Remodelación y ampliación de una casa proyectada originalmente por el arquitecto Christian de Groote. Se buscó mantener la amplitud de los espacios originales e incorporar los nuevos recintos con una lectura contemporánea y homogénea, sin una ampliación visible. Se sumaron un área de servicios y un segundo piso, y se modificaron casi todos los recintos, salvo el hall, el living y el comedor.", "facts": [["Arquitectura", "Ramírez Moletto Arquitectos + Elton Leniz Arquitectos"], ["Años", "2008–2010"], ["Estado", "Construida"], ["Fotografía", "Natalia Vial"]], "gallery": [["aguadelpalo-editorial-1.webp", "Fachada hacia la calle"], ["aguadelpalo-editorial-2.webp", "Acceso iluminado"], ["aguadelpalo-editorial-3.webp", "Volumen superior revestido en madera"], ["aguadelpalo-editorial-4.webp", "Muros de acceso"]], "next": "lavandulas", "nextTitle": "Casa Lavándulas"}, "unabconce": {"title": "UNAB Concepción", "headline": "Una columna vertebral frente al viento sur.", "place": "Talcahuano, Concepción", "type": "Educación / Obra por etapas", "image": "unabconce-editorial-0.webp", "alt": "Edificio de la Universidad Andrés Bello en Concepción", "sub": "Un campus en seis etapas.", "text": "El edificio albergará doce carreras y se desarrolla en seis etapas. El cuerpo principal, hacia el límite sur, libera el terreno norte para aprovechar el asoleamiento y protege el predio del viento sur. Tres cuerpos de aulas se desprenden perpendicularmente, desfasados medio piso y conectados por rampas en un hall central; entre ellos, parques que llevan luz y vegetación al interior.", "facts": [["Arquitectura", "Ramírez Moletto Arquitectos + S3 Arquitectos Asociados"], ["Años", "2008–2010"], ["Superficie", "26.000 m²"], ["Programa", "Doce carreras, seis etapas"], ["Imágenes", "Fotografías y visualizaciones"]], "gallery": [["unabconce-editorial-1.webp", "Hall central"], ["unabconce-editorial-2.webp", "Cuerpo principal y aulas"], ["unabconce-editorial-3.webp", "Visualización del patio"]], "next": "aguadelpalo", "nextTitle": "Casa Agua del Palo"}, "yunis": {"title": "Casa Yunis-Alcántara", "headline": "Hacia la cordillera.", "place": "Los Dominicos, Santiago", "type": "Vivienda / Obra construida", "image": "yunis-editorial-0.webp", "alt": "Casa Yunis-Alcántara desde la calle, con muros de hormigón y madera", "sub": "Pendiente y vistas.", "text": "Vivienda unifamiliar que aprovecha la pendiente del terreno y la vista hacia la cordillera. El primer nivel reúne los espacios comunes y el segundo los privados, articulados por un patio interior que contiene la escalera. Los dormitorios principales se desfasan en torno a una terraza para favorecer las vistas. Hormigón visto y madera son los materiales principales.", "facts": [["Arquitectura", "Ramírez Moletto Arquitectos"], ["Años", "2008–2010"], ["Superficie", "340 m²"], ["Estado", "Construida"]], "gallery": [["yunis-editorial-1.webp", "Acceso y volumen superior"], ["yunis-editorial-2.webp", "Terraza"], ["yunis-editorial-3.webp", "Escalera en el patio interior"], ["yunis-editorial-4.webp", "Vista hacia la cordillera"]], "next": "roxy", "nextTitle": "Tiendas Roxy"}, "roxy": {"title": "Tiendas Roxy", "headline": "Una fachada de madera.", "place": "Parque Arauco, Santiago", "type": "Comercio / Obra construida", "image": "roxy-editorial-0.webp", "alt": "Fachada de la tienda Roxy en Parque Arauco", "sub": "Interiorismo comercial.", "text": "Tiendas para la marca Roxy en Parque Arauco y Portal La Dehesa. Un revestimiento de madera define la fachada y enmarca la vitrina.", "facts": [["Arquitectura", "OF Arquitectos + Elton Leniz Arquitectos"], ["Año", "2010"], ["Superficie", "120 m²"], ["Estado", "Construido"], ["Fotografía", "Francisco Cepeda"]], "gallery": [["roxy-editorial-1.webp", "Vitrina"], ["roxy-editorial-2.webp", "Interior de la tienda"]], "next": "buchupureo", "nextTitle": "Casa Buchupureo"}, "conejero": {"title": "Casa Conejero", "headline": "Una casa de madera entre pinos.", "place": "Punta Puertecillo, Litueche", "type": "Vivienda / Obra construida", "image": "conejero-editorial-0.webp", "alt": "Casa Conejero, volúmenes de madera unidos por una pasarela", "sub": "Junto a la quebrada.", "text": "Vivienda proyectada íntegramente en madera, emplazada junto a una quebrada, rodeada de un bosque de pinos y con vistas al mar.", "facts": [["Arquitectura", "Álvaro Ramírez, Francisco Cepeda, Sebastián Cifuentes"], ["Año", "2015"], ["Terreno", "5.000 m²"], ["Superficie", "370 m²"], ["Cálculo", "Alex Popp"]], "gallery": [["conejero-editorial-1.webp", "La casa entre el bosque de pinos"]], "next": "camino", "nextTitle": "Casa Camino el Alto"}, "ibanez": {"title": "Edificio Consistorial de Río Ibáñez", "headline": "Un edificio público en la Patagonia.", "place": "Puerto Ingeniero Ibáñez, Aysén", "type": "Edificio público / Proyecto", "image": "ibanez-editorial-0.webp", "alt": "Visualización del Edificio Consistorial de Río Ibáñez", "sub": "Municipio y territorio.", "text": "Proyecto para el edificio consistorial de la comuna de Río Ibáñez, en la Región de Aysén. Un volumen bajo revestido en madera se extiende a lo largo del terreno y acompaña una gran cubierta inclinada que capta la luz.", "facts": [["Arquitectura", "OF + Cavagnaro Rojo"], ["Año", "2020"], ["Terreno", "42.700 m²"], ["Superficie", "7.400 m²"], ["Imágenes", "Visualizaciones del proyecto"]], "gallery": [["ibanez-editorial-1.webp", "Acceso y cubierta inclinada"], ["ibanez-editorial-2.webp", "Vista nocturna"], ["ibanez-editorial-3.webp", "Oficinas abiertas al paisaje"]], "next": "contador", "nextTitle": "Casa Lo Contador"}, "fg": {"title": "Casa FG", "headline": "Un mirador sobre Puertecillo.", "place": "Punta Puertecillo, Litueche", "type": "Vivienda / Obra construida", "image": "fg-editorial-0.webp", "alt": "Casa FG, volumen elevado sobre estructura de madera", "sub": "Sobre un promontorio.", "text": "La vivienda se emplaza sobre un promontorio del terreno, en posición de mirador sobre la playa de Puertecillo.", "facts": [["Arquitectura", "Álvaro Ramírez, Francisco Cepeda"], ["Años", "2015–2018"], ["Terreno", "5.000 m²"], ["Superficie", "340 m²"], ["Cálculo", "Enzo Valladares"]], "next": "ensignia", "nextTitle": "Casa Ensignia Gerber"}, "abs": {"title": "Antofagasta British School", "headline": "Un plano en la ladera.", "place": "Antofagasta, Chile", "type": "Educación / Concurso", "image": "abs-editorial-0.webp", "alt": "Visualización del colegio sobre la cancha de rugby", "sub": "Deporte e identidad.", "text": "La cancha de rugby ocupa cerca de la mitad del terreno y debe ser un plano absoluto en la falda de un cerro. Esa condición ordena el proyecto. El colegio pidió además un sello deportivo, por lo que la posición de la cancha es también clave para su identidad.", "facts": [["Arquitectura", "OF Arquitectos"], ["Concurso", "Tercer lugar"], ["Año", "2016"], ["Superficie", "12.000 m²"], ["Imágenes", "Visualizaciones del concurso"]], "chapters": [["Contención y abalconamiento.", "El terreno se escalona: la cancha queda en la parte baja, entre dos contenciones, mitad excavada y mitad rellena. Abajo, hacia el mar y la ciudad, el programa deportivo; arriba, sobre una plataforma única, el programa docente y administrativo.", [["editorial-4", "La cancha de rugby frente al colegio."], ["editorial-1", "Vista desde la plataforma superior."]]], ["Patios y recorridos.", "Desde la plataforma superior, los recorridos y espacios principales miran hacia la cancha y la ciudad.", [["editorial-2", "Patio de juegos."], ["editorial-3", "Espacio de encuentro bajo la cubierta."]]], ["Aulas.", "Las aulas se abren a patios arbolados.", [["editorial-5", "Patio arbolado."], ["editorial-6", "Sala abierta al patio."]]]], "next": "faad", "nextTitle": "FAAD UDP"}, "contador": {"title": "Casa Lo Contador", "headline": "Patios en una casa de los años sesenta.", "place": "Providencia, Santiago", "type": "Vivienda / Obra construida", "image": "contador-editorial-0.webp", "alt": "Celosía cerámica y jardín de la Casa Lo Contador", "sub": "Liberar el primer piso.", "text": "Remodelación de una casa de los años sesenta. La propuesta libera el espacio del primer piso e incorpora luz natural a través de una serie de patios interiores e intermedios.", "facts": [["Arquitectura", "Álvaro Ramírez, Clarisa Elton"], ["Año proyecto", "2013"], ["Terreno", "600 m²"], ["Superficie", "330 m²"], ["Paisajismo", "María Inés Couve"], ["Construcción", "Farco"], ["Cálculo", "Alex Popp"]], "chapters": [["Planta libre.", "El primer piso se abre como un espacio continuo, con vistas cruzadas hacia los patios.", [["editorial-3", "Estar hacia el patio."], ["editorial-4", "Escalera y luz lateral."]]], ["Patios.", "Patios interiores e intermedios llevan luz y vegetación al centro de la casa.", [["editorial-5", "Patio interior."], ["editorial-6", "Circulación junto al patio."]]], ["Terraza y jardín.", "Una pérgola prolonga el interior hacia el jardín.", [["editorial-1", "Terraza hacia el jardín."], ["editorial-2", "Pérgola."]]]], "next": "museo", "nextTitle": "Museo de la Memoria y DD. HH. del Biobío"}, "palmas": {"title": "Strip center Las Palmas", "headline": "Comercio frente a la costa.", "place": "El Tabo, Región de Valparaíso", "type": "Comercio / Proyecto", "image": "palmas-editorial-0.webp", "alt": "Visualización del strip center Las Palmas", "sub": "Un centro comercial de dos niveles.", "text": "Centro comercial de dos niveles en El Tabo. Una galería perimetral ordena los locales y los recorridos hacia el estacionamiento.", "facts": [["Arquitectura", "Francisco Cepeda, Álvaro Ramírez"], ["Arquitecto asociado", "BAUEN Arquitectos"], ["Año", "2019"], ["Superficie", "2.500 m²"], ["Imágenes", "Visualizaciones del proyecto"]], "gallery": [["palmas-editorial-1.webp", "Galería y accesos"], ["palmas-editorial-2.webp", "Vista aérea del conjunto"]], "next": "mallarauco", "nextTitle": "Casa Mallarauco"}});
Object.assign(englishProjects,{"lavandulas": {"title": "Casa Lavándulas", "headline": "A house open to the garden.", "place": "Las Condes, Santiago", "type": "Private house / Built", "image": "lavandulas-editorial-0.webp", "alt": "Casa Lavándulas seen from the garden, with its continuous white eave", "sub": "A house on a wooded site.", "text": "Renovation of a single-storey house in Las Condes, on a 1,600 m² site with existing trees. The project reorganises 250 m² of built area around the garden and a sequence of terraces.", "facts": [["Architecture", "OF Arquitectos"], ["Design", "2010"], ["Completion", "2011"], ["Area", "250 m²"], ["Structure", "Alex Popp"], ["Contractor", "RCubo"], ["Photography", "Francisco Cepeda"]], "chapters": [["House and garden.", "A continuous white eave orders the garden façade and shelters the terraces. The existing trees remain part of the project.", [["editorial-1", "Garden façade among the existing trees."], ["editorial-2", "Eave and terrace."]]], ["Pergola and courtyard.", "A timber pergola filters light over the terrace. The entrance is reached through a planted courtyard.", [["editorial-3", "Terrace beneath the timber pergola."], ["editorial-4", "Entrance courtyard."]]], ["Interior.", "Timber and white surfaces give continuity to the rooms, which open to the outside.", [["editorial-5", "Kitchen."], ["editorial-6", "Dining room open to the courtyard."]]]], "next": "yunis", "nextTitle": "Casa Yunis-Alcántara"}, "estadio": {"title": "Estadio Español sports building", "headline": "A meeting place for sport.", "place": "Las Condes, Santiago", "type": "Sport / Project", "image": "estadio-editorial-0.webp", "alt": "Façade of the Estadio Español sports building", "sub": "Bringing scattered programmes together.", "text": "Sports in this part of the club operated separately. The project brings together gym, artistic gymnastics, spa, offices, changing rooms and multipurpose rooms, and forms the main entrance to the neighbouring buildings. Its proportions follow the adjacent buildings, and its white materiality avoids competing with them.", "facts": [["Architecture", "OF Arquitectos + Pasiva"], ["Competition", "First prize, 2010"], ["Year", "2014"], ["Area", "6,500 m²"], ["Images", "Architectural visualisations"]], "chapters": [["A shared entrance.", "The building organises movement through the club, from the fronton and basketball courts to the east to the indoor pool to the west.", [["editorial-1", "Entrance and courtyard."], ["editorial-2", "Entrance hall."]]], ["Transparency.", "Rooms are visually connected, allowing different activities and encouraging encounters between members.", [["editorial-3", "Court and circulation."], ["editorial-4", "Fitness room."]]], ["Gymnastics and spa.", "Artistic gymnastics and the spa complete a programme experienced as a continuous sequence.", [["editorial-5", "Artistic gymnastics."], ["editorial-6", "Spa."]]]], "next": "fg", "nextTitle": "Casa FG"}, "fee": {"title": "UDP School of Economics and Business", "headline": "Two buildings and a place to meet.", "place": "Huechuraba, Santiago", "type": "Education / Competition", "image": "fee-editorial-0.webp", "alt": "Visualisation of the UDP School of Economics and Business from the avenue", "sub": "A campus proposal.", "text": "The brief is resolved in two connected buildings, for undergraduate and graduate studies. Beneath them, a two-level basement holds the shared programme. A steel walkway designed to carry planting links both buildings and activates the space between them as a meeting place.", "facts": [["Architecture", "Álvaro Ramírez, Francisco Cepeda, C. Briones"], ["Competition", "Second prize"], ["Year", "2010"], ["Area", "15,000 m²"], ["Images", "Competition visualisations"]], "chapters": [["Between two buildings.", "The walkway works both as a connection and as an ordering element for the campus. The void between buildings becomes the main gathering space.", [["editorial-1", "Terrace beneath the walkway."], ["editorial-2", "Entrance and plaza."]]], ["Energy strategy.", "Programme is placed according to intensity of use: intensive uses below ground, continuous uses protected and with views, occasional uses facing the promenade. Natural ventilation, specific façades, green barriers and geothermal energy complete the strategy.", [["editorial-3", "Space between buildings."], ["editorial-4", "Approach to the building."]]], ["The campus.", "The proposal sets out criteria for future buildings on the campus.", [["editorial-5", "Overall view."]]]], "next": "unabconce", "nextTitle": "UNAB Concepción"}, "aguadelpalo": {"title": "Casa Agua del Palo", "headline": "Extending without showing it.", "place": "Vitacura, Santiago", "type": "Private house / Built", "image": "aguadelpalo-editorial-0.webp", "alt": "Casa Agua del Palo at dusk from the street", "sub": "A house by Christian de Groote.", "text": "Renovation and extension of a house originally designed by architect Christian de Groote. The aim was to keep the generosity of the original spaces and add new rooms with a contemporary, homogeneous reading, with no visible extension. A service area and an upper floor were added, and almost every room was modified except the hall, living and dining rooms.", "facts": [["Architecture", "Ramírez Moletto Arquitectos + Elton Leniz Arquitectos"], ["Years", "2008–2010"], ["Status", "Built"], ["Photography", "Natalia Vial"]], "gallery": [["aguadelpalo-editorial-1.webp", "Street façade"], ["aguadelpalo-editorial-2.webp", "Lit entrance"], ["aguadelpalo-editorial-3.webp", "Timber-clad upper volume"], ["aguadelpalo-editorial-4.webp", "Entrance walls"]], "next": "lavandulas", "nextTitle": "Casa Lavándulas"}, "unabconce": {"title": "UNAB Concepción", "headline": "A spine against the south wind.", "place": "Talcahuano, Concepción", "type": "Education / Phased construction", "image": "unabconce-editorial-0.webp", "alt": "Universidad Andrés Bello building in Concepción", "sub": "A campus in six phases.", "text": "The building will house twelve degree programmes and is developed in six phases. The main block, on the southern edge, frees the northern part of the site for sunlight and shelters it from the prevailing south wind. Three classroom wings extend perpendicularly, offset by half a level and linked by ramps in a central hall; between them, gardens bring light and vegetation inside.", "facts": [["Architecture", "Ramírez Moletto Arquitectos + S3 Arquitectos Asociados"], ["Years", "2008–2010"], ["Area", "26,000 m²"], ["Programme", "Twelve degrees, six phases"], ["Images", "Photographs and visualisations"]], "gallery": [["unabconce-editorial-1.webp", "Central hall"], ["unabconce-editorial-2.webp", "Main block and classrooms"], ["unabconce-editorial-3.webp", "Courtyard visualisation"]], "next": "aguadelpalo", "nextTitle": "Casa Agua del Palo"}, "yunis": {"title": "Casa Yunis-Alcántara", "headline": "Towards the Andes.", "place": "Los Dominicos, Santiago", "type": "Private house / Built", "image": "yunis-editorial-0.webp", "alt": "Casa Yunis-Alcántara from the street, with concrete and timber walls", "sub": "Slope and views.", "text": "A family house that makes use of the slope and the view towards the Andes. The ground floor holds the shared spaces and the upper floor the private rooms, organised around an inner courtyard containing the stair. The main bedrooms are offset around a terrace to open up views. Exposed concrete and timber are the main materials.", "facts": [["Architecture", "Ramírez Moletto Arquitectos"], ["Years", "2008–2010"], ["Area", "340 m²"], ["Status", "Built"]], "gallery": [["yunis-editorial-1.webp", "Entrance and upper volume"], ["yunis-editorial-2.webp", "Terrace"], ["yunis-editorial-3.webp", "Stair in the inner courtyard"], ["yunis-editorial-4.webp", "View towards the Andes"]], "next": "roxy", "nextTitle": "Roxy stores"}, "roxy": {"title": "Roxy stores", "headline": "A timber façade.", "place": "Parque Arauco, Santiago", "type": "Retail / Built", "image": "roxy-editorial-0.webp", "alt": "Roxy store façade at Parque Arauco", "sub": "Retail interiors.", "text": "Stores for the Roxy brand at Parque Arauco and Portal La Dehesa. Timber cladding defines the façade and frames the shop window.", "facts": [["Architecture", "OF Arquitectos + Elton Leniz Arquitectos"], ["Year", "2010"], ["Area", "120 m²"], ["Status", "Built"], ["Photography", "Francisco Cepeda"]], "gallery": [["roxy-editorial-1.webp", "Shop window"], ["roxy-editorial-2.webp", "Store interior"]], "next": "buchupureo", "nextTitle": "Casa Buchupureo"}, "conejero": {"title": "Casa Conejero", "headline": "A timber house among pines.", "place": "Punta Puertecillo, Litueche", "type": "Private house / Built", "image": "conejero-editorial-0.webp", "alt": "Casa Conejero, timber volumes linked by a bridge", "sub": "Beside the ravine.", "text": "A house built entirely in timber, set beside a ravine, surrounded by pine forest and with views to the sea.", "facts": [["Architecture", "Álvaro Ramírez, Francisco Cepeda, Sebastián Cifuentes"], ["Year", "2015"], ["Site", "5,000 m²"], ["Area", "370 m²"], ["Structure", "Alex Popp"]], "gallery": [["conejero-editorial-1.webp", "The house within the pine forest"]], "next": "camino", "nextTitle": "Casa Camino el Alto"}, "ibanez": {"title": "Río Ibáñez Town Hall", "headline": "A public building in Patagonia.", "place": "Puerto Ingeniero Ibáñez, Aysén", "type": "Public building / Project", "image": "ibanez-editorial-0.webp", "alt": "Visualisation of the Río Ibáñez Town Hall", "sub": "Municipality and territory.", "text": "Project for the town hall of the Río Ibáñez municipality, in the Aysén Region. A low timber-clad volume extends along the site alongside a large pitched roof that captures daylight.", "facts": [["Architecture", "OF + Cavagnaro Rojo"], ["Year", "2020"], ["Site", "42,700 m²"], ["Area", "7,400 m²"], ["Images", "Architectural visualisations"]], "gallery": [["ibanez-editorial-1.webp", "Entrance and pitched roof"], ["ibanez-editorial-2.webp", "Night view"], ["ibanez-editorial-3.webp", "Offices open to the landscape"]], "next": "contador", "nextTitle": "Casa Lo Contador"}, "fg": {"title": "Casa FG", "headline": "A lookout over Puertecillo.", "place": "Punta Puertecillo, Litueche", "type": "Private house / Built", "image": "fg-editorial-0.webp", "alt": "Casa FG, raised volume on a timber structure", "sub": "On a promontory.", "text": "The house sits on a promontory of the site, as a lookout over Puertecillo beach.", "facts": [["Architecture", "Álvaro Ramírez, Francisco Cepeda"], ["Years", "2015–2018"], ["Site", "5,000 m²"], ["Area", "340 m²"], ["Structure", "Enzo Valladares"]], "next": "ensignia", "nextTitle": "Casa Ensignia Gerber"}, "abs": {"title": "Antofagasta British School", "headline": "A level plane on the hillside.", "place": "Antofagasta, Chile", "type": "Education / Competition", "image": "abs-editorial-0.webp", "alt": "Visualisation of the school above the rugby pitch", "sub": "Sport and identity.", "text": "The rugby pitch occupies almost half the site and must be perfectly level on a hillside. That condition orders the project. The school also asked for a strong sporting identity, which makes the position of the pitch central.", "facts": [["Architecture", "OF Arquitectos"], ["Competition", "Third prize"], ["Year", "2016"], ["Area", "12,000 m²"], ["Images", "Competition visualisations"]], "chapters": [["Retaining and overlooking.", "The site is terraced: the pitch sits at the lower level between two retaining walls, half cut and half fill. Below, facing the sea and the city, the sports programme; above, on a single platform, teaching and administration.", [["editorial-4", "The rugby pitch in front of the school."], ["editorial-1", "View from the upper platform."]]], ["Courtyards and routes.", "From the upper platform, the main routes and spaces look towards the pitch and the city.", [["editorial-2", "Play courtyard."], ["editorial-3", "Meeting space beneath the roof."]]], ["Classrooms.", "Classrooms open onto tree-lined courtyards.", [["editorial-5", "Tree-lined courtyard."], ["editorial-6", "Classroom open to the courtyard."]]]], "next": "faad", "nextTitle": "FAAD UDP"}, "contador": {"title": "Casa Lo Contador", "headline": "Courtyards in a 1960s house.", "place": "Providencia, Santiago", "type": "Private house / Built", "image": "contador-editorial-0.webp", "alt": "Ceramic lattice and garden of Casa Lo Contador", "sub": "Freeing the ground floor.", "text": "Renovation of a 1960s house. The proposal frees the ground floor and brings in daylight through a series of inner and intermediate courtyards.", "facts": [["Architecture", "Álvaro Ramírez, Clarisa Elton"], ["Design", "2013"], ["Site", "600 m²"], ["Area", "330 m²"], ["Landscape", "María Inés Couve"], ["Contractor", "Farco"], ["Structure", "Alex Popp"]], "chapters": [["Open plan.", "The ground floor opens as a continuous space, with views across to the courtyards.", [["editorial-3", "Living room towards the courtyard."], ["editorial-4", "Stair and side light."]]], ["Courtyards.", "Inner and intermediate courtyards bring light and planting into the centre of the house.", [["editorial-5", "Inner courtyard."], ["editorial-6", "Circulation beside the courtyard."]]], ["Terrace and garden.", "A pergola extends the interior towards the garden.", [["editorial-1", "Terrace towards the garden."], ["editorial-2", "Pergola."]]]], "next": "museo", "nextTitle": "Biobío Museum of Memory and Human Rights"}, "palmas": {"title": "Las Palmas strip centre", "headline": "Retail by the coast.", "place": "El Tabo, Región de Valparaíso", "type": "Retail / Project", "image": "palmas-editorial-0.webp", "alt": "Visualisation of the Las Palmas strip centre", "sub": "A two-level shopping centre.", "text": "Two-level shopping centre in El Tabo. A perimeter gallery organises the shops and the routes to the car park.", "facts": [["Architecture", "Francisco Cepeda, Álvaro Ramírez"], ["Associate architect", "BAUEN Arquitectos"], ["Year", "2019"], ["Area", "2,500 m²"], ["Images", "Architectural visualisations"]], "gallery": [["palmas-editorial-1.webp", "Gallery and entrances"], ["palmas-editorial-2.webp", "Aerial view"]], "next": "mallarauco", "nextTitle": "Casa Mallarauco"}});
projects.museo.text="El proyecto se formula como un sistema de espacios públicos. Una plaza pone en valor el memorial existente y lo convierte en un lugar; una plaza hundida propia organiza el programa del museo; y una explanada hacia el río, con un mirador, acoge tanto la actividad cotidiana como eventos masivos. El equipo obtuvo el primer lugar del concurso. El proyecto no ha sido construido.";
englishProjects.museo.text="The project is conceived as a system of public spaces. A plaza gives value to the existing memorial and turns it into a place; a sunken plaza organises the museum programme; and an esplanade towards the river, with a lookout, hosts both everyday activity and large gatherings. The team won first prize in the competition. The project has not been built.";
projects.museo.gallery=[["museo-editorial-0.webp","Plaza hundida del museo"]];englishProjects.museo.gallery=[["museo-editorial-0.webp","The museum's sunken plaza"]];
