englishProjects.unab.gallery=[["unab-vina-2026-aerea.webp","Aerial view of the campus"],["unab-vina-2026-llegada.webp","Arrival at the campus"],["unab-vina-2026-circulacion.webp","Outdoor circulation"],["unab-vina-2026-cubierta.webp","Roof terrace towards the bay"],["unab-vina-2026-canchas.webp","Rooftop courts"]];
