Object.assign(projects,{"udla-conce": {"title": "UDLA Concepción", "headline": "Un parque como corazón del campus.", "place": "Campus El Boldal, Concepción", "type": "Educación / En desarrollo", "image": "udla-conce-hero-rearframe-2026.webp", "video": "udla-conce.mp4", "poster": "udla-conce-poster.webp", "videoCaption": "Video del concurso.", "alt": "Visualización del campus UDLA Concepción desde la avenida", "sub": "Plan maestro. Primer lugar en concurso.", "text": "Plan maestro para el Campus El Boldal de la Universidad de las Américas, primer lugar junto a MSRAA en el concurso convocado a fines de 2025 y adjudicado en 2026. El proyecto entiende el campus como una Ciudad Jardín Universitaria: un sistema abierto, estructurado por el paisaje, en el que la arquitectura construye bordes activos en torno a un Parque Interior que actúa como corazón académico, social y ambiental. Se desarrolla en dos fases.", "facts": [["Arquitectura", "MSRAA + OF Arquitectos"], ["Concurso", "Primer lugar, 2026"], ["Año", "2026"], ["Superficie", "7.500 m²"], ["Estado", "En desarrollo"], ["Imágenes", "Visualizaciones del proyecto"]], "chapters": [["Plazas y graderías.", "Los edificios se separan para formar espacios públicos: una plaza de acceso, graderías y patios sombreados que funcionan como lugar de encuentro.", [["editorial-2", "Plaza y graderías entre edificios."], ["editorial-3", "Patio de acceso bajo los volúmenes."]]], ["Frente urbano.", "Hacia la avenida, el conjunto presenta una fachada continua con un zócalo transparente y celosías en los niveles superiores.", [["editorial-0", "El campus al atardecer."], ["editorial-1", "Fachada hacia la avenida."]]], ["Interiores.", "Auditorio y circulaciones interiores prolongan la materialidad de madera y metal del exterior.", [["editorial-4", "Circulación interior."], ["editorial-5", "Auditorio."]]]], "next": "udla-provi", "nextTitle": "UDLA Providencia"}, "udla-provi": {"title": "UDLA Providencia", "headline": "El patio en vertical.", "place": "Providencia, Santiago", "type": "Educación / En desarrollo", "image": "udla-provi-editorial-0.webp", "alt": "Visualización de la nueva sede UDLA Providencia desde la calle", "video": "udla-provi.mp4", "poster": "udla-provi-poster.webp", "videoCaption": "Video del concurso.", "sub": "Nueva sede. Primer lugar en concurso.", "text": "Nueva sede de la Universidad de las Américas en Providencia, primer lugar junto a MSRAA en el concurso convocado a fines de 2025 y adjudicado en 2026. El proyecto recoge los criterios con que Germán Bannen definió la comuna —continuidad peatonal, escala humana, áreas verdes y mezcla de usos— y los traslada a un edificio en altura: la ciudad no termina en la línea oficial, continúa dentro de la manzana.", "facts": [["Arquitectura", "MSRAA + OF Arquitectos"], ["Concurso", "Primer lugar, 2026"], ["Año", "2026"], ["Superficie", "7.500 m²"], ["Estado", "En desarrollo"], ["Imágenes", "Visualizaciones del concurso"]], "chapters": [["Una plataforma urbana.", "El primer nivel se eleva para construir una plataforma que ordena los flujos, permite traspasos peatonales y extiende el espacio público hacia el interior del edificio.", [["editorial-1", "El edificio desde la calle."], ["editorial-2", "Esquina y acceso."]]], ["Patios elevados.", "Los patios de las casonas de la zona central organizan el programa y regulan el clima. Aquí se trasladan en vertical: vacíos y patios elevados para el encuentro académico, con continuidad visual y ventilación cruzada.", [["editorial-3", "Espacio de encuentro con vista a la cordillera."], ["editorial-4", "Patio elevado."]]], ["Abierto a la comunidad.", "Los programas más públicos —un auditorio para 400 personas, el espacio de exhibición y las clínicas de atención a la comunidad— se ubican en los primeros niveles y funcionan con independencia de la universidad.", [["editorial-5", "Auditorio."], ["editorial-6", "Espacio de exhibición."], ["editorial-7", "Fachada principal."]]]], "next": "cla", "nextTitle": "Colegio Los Andes"}, "cla": {"title": "Colegio Los Andes", "headline": "Un patio cívico para el colegio.", "place": "Santiago", "type": "Educación / Concurso", "image": "cla-editorial-0.webp", "alt": "Visualización del nuevo acceso del Colegio Los Andes", "sub": "Plan maestro. Segundo lugar en concurso.", "text": "Plan maestro para el Colegio Los Andes, colegio de niñas fundado en 1967, en un sitio de meseta entre las calles San Damián y Las Hualtatas. El proyecto reorganiza el acceso y los patios del colegio: una nueva fachada de hormigón con una piel de celosías de madera prefabricada regula el clima del recinto, un patio cívico se convierte en el nuevo centro del colegio junto a la capilla existente, y un edificio nuevo —el Edificio L— reúne casino, auditorio y biblioteca. La Pre-Básica se traslada a un pabellón propio.", "facts": [["Arquitectura", "OF + TNG"], ["Concurso", "Segundo lugar, 2024"], ["Año", "2024"], ["Estado", "Anteproyecto"], ["Imágenes", "Visualizaciones del concurso"]], "chapters": [["El patio cívico.", "Un patio cívico organiza el conjunto junto a la capilla existente, con una estructura de hormigón que enmarca el paso entre los edificios.", [["editorial-3", "El patio cívico junto a los edificios de aulas."], ["editorial-1", "El patio de la capilla."]]], ["Pre-Básica y deporte.", "La Pre-Básica se traslada a un pabellón propio con salas volcadas hacia el patio de juegos, y el conjunto incorpora un nuevo edificio deportivo junto a la pista atlética.", [["editorial-2", "Sala de estar de la Pre-Básica."], ["editorial-4", "El edificio deportivo junto a la pista atlética."]]]], "next": "cdv", "nextTitle": "Curaco de Vélez"}, "cdv": {"title": "Curaco de Vélez", "headline": "Un gran poncho de madera.", "place": "Curaco de Vélez, Chiloé", "type": "Edificio público / Concurso", "image": "cdv-editorial-0.webp", "alt": "Visualización nocturna del Edificio Consistorial de Curaco de Vélez", "sub": "Edificio Consistorial. Concurso público.", "text": "Nuevo Edificio Consistorial para Curaco de Vélez, en un terreno de 75 x 40 m frente a la Plaza Central de este pueblo de Chiloé. El proyecto propone un gran interior, una \u201cesclusa urbana\u201d: una nave acristalada recorre el edificio y conecta sus programas, protegida por una estructura de madera inspirada en el poncho williche. Una de las dos naves es translúcida, un invernadero de vidrio que alberga el auditorio y la feria artesanal en el primer nivel, con la Alcaldía y la Sala de Consejo colgando del segundo. Madera laminada, acero Aluzinc y cristal articulan la estructura y la fachada.", "facts": [["Arquitectura", "OF Arquitectos"], ["Concurso", "2024"], ["Año", "2024"], ["Superficie del terreno", "75 x 40 m"], ["Estado", "Anteproyecto"], ["Imágenes", "Visualizaciones del concurso"]], "gallery": [["cdv-editorial-1.webp", "El edificio en su emplazamiento, frente a las calles del pueblo."]], "next": "numu", "nextTitle": "NUMU"}, "numu": {"title": "NUMU", "headline": "El gabinete de curiosidades.", "place": "Parque Bicentenario, Vitacura", "type": "Cultura / Concurso", "image": "numu-editorial-0.webp", "alt": "Visualización del hall de acceso del Nuevo Museo de Santiago (NUMU)", "sub": "Nuevo Museo de Santiago. Concurso público.", "text": "Propuesta para el concurso del Nuevo Museo de Santiago (NUMU), junto al Parque Bicentenario en Vitacura, en asociación con Elton Léniz y MCRJAG. El edificio se presenta como un volumen monocromático y silencioso, envuelto en una pantalla que deja pasar la luz y permite que el Parque se adentre en un patio de acceso vertical antes de transformarse en un gran hall continuo de hormigón blanco. Sobre este hall flotan las salas de exposición, unidas por un puente y por una gran escalera-gradería que conecta con la calle. Un núcleo de circulaciones lleva a las salas, el auditorio, un patio circular en el subterráneo y una terraza de esculturas en la cubierta, con vista al Parque y al cerro San Cristóbal.", "facts": [["Arquitectura", "OF + Elton Léniz + MCRJAG"], ["Concurso", "2020"], ["Año", "2020"], ["Estado", "Anteproyecto"], ["Imágenes", "Visualizaciones del concurso"]], "gallery": [["numu-editorial-1.webp", "La escalera-gradería y el puente sobre el hall."], ["numu-editorial-2.webp", "Sala de exposiciones y vista hacia la terraza ajardinada."]], "next": "las-salinas", "nextTitle": "Las Salinas"}, "las-salinas": {"title": "Las Salinas", "headline": "Cinco cuerpos sobre el borde costero.", "place": "Viña del Mar, Chile", "type": "Vivienda colectiva / En desarrollo", "image": "las-salinas-editorial-0.webp", "alt": "Visualización del anteproyecto Las Salinas desde la avenida, Viña del Mar", "sub": "Uno de los lotes del Plan Maestro Barrio Las Salinas, en colaboración con TNG.", "text": "Anteproyecto de vivienda colectiva y placa comercial para uno de los terrenos del Plan Maestro Barrio Las Salinas, en Viña del Mar, un plan de 16 hectáreas de TNG para Inmobiliaria Las Salinas (Empresas COPEC). OF colabora con TNG en el diseño de este lote. El programa se organiza en un basamento comercial continuo que da a la calle, sobre el cual se levantan cinco volúmenes de altura escalonada, revestidos en una piel vertical de celosías que controla el asoleamiento y unifica el conjunto.", "facts": [["Arquitectura", "OF + TNG"], ["Plan maestro", "Barrio Las Salinas, TNG"], ["Superficie", "95.000 m²"], ["Ubicación", "Viña del Mar"], ["Año", "2026"], ["Estado", "Anteproyecto"], ["Imágenes", "Visualización del anteproyecto"]], "next": "guadal-mixto", "nextTitle": "Casona Guadal"}, "guadal-mixto": {"title": "Casona Guadal", "headline": "Tres cuerpos frente a la plaza.", "place": "Puerto Guadal, Aysén", "type": "Vivienda colectiva / En desarrollo", "image": "guadal-mixto-editorial-0.webp", "alt": "Visualización de Casona Guadal, fachada poniente", "sub": "Un edificio de uso mixto en un pueblo de baja altura.", "text": "Edificio de tres niveles en una esquina frente a la plaza de Puerto Guadal. El nivel de calle aloja locales comerciales, entre ellos una farmacia de barrio; los niveles superiores contienen ocho unidades residenciales de renta. Para introducir esta escala en un pueblo de casas de dos pisos, el volumen se fragmenta en tres cuerpos que se leen como construcciones aisladas.", "facts": [["Arquitectura", "Francisco Cepeda + Juan José Mena"], ["Año", "2026"], ["Superficie", "600 m²"], ["Programa", "Locales comerciales y ocho unidades residenciales"], ["Estado", "En desarrollo"], ["Imágenes", "Visualizaciones del proyecto"]], "chapters": [["La lógica de los colonos.", "Los colonos de Aysén no construían una casa única sino un conjunto de piezas: la casa, la cocina fogón, el galpón. El proyecto recoge esa lógica. Los tres cuerpos comparten volumen simple, cubierta a dos aguas y revestimiento de madera, y se distinguen por el dibujo del entablado: vertical, horizontal y diagonal.", [["editorial-1", "Vista desde la plaza."], ["editorial-3", "Fachada poniente."], ["editorial-7", "Vista del conjunto desde la iglesia."]]], ["Una prolongación de la vereda.", "El nivel comercial continúa la vereda frente a la plaza. Una marquesina longitudinal unifica el recorrido y protege de la lluvia; la farmacia ocupa el cuerpo norte y el café, la esquina.", [["editorial-4", "Locales comerciales y marquesina."], ["editorial-6", "Pasarela de acceso a las unidades."]]], ["Luz de mañana y de tarde.", "Una pasarela metálica en la cara oriente da acceso a las unidades y deja limpia la fachada urbana. Todas las unidades reciben luz de mañana y de tarde y tienen ventilación cruzada; la cubierta genera dobles alturas y altillos.", [["editorial-2", "Interior de una unidad residencial."], ["editorial-5", "Sección habitada."]]]], "next": "carrere", "nextTitle": "Casa Carrere"}, "carrere": {"title": "Casa Carrere", "headline": "Una casa abierta al jardín.", "place": "Vitacura, Santiago", "type": "Vivienda / En construcción", "image": "carrere-editorial-0.webp", "alt": "Visualización nocturna de la Casa Carrere desde el jardín", "sub": "En curso.", "text": "Remodelación de una vivienda en Vitacura. La planta baja se abre hacia el jardín mediante una terraza cubierta y grandes ventanales; al interior, la cocina, el estar y una escalera de caracol roja organizan los espacios comunes. La obra está en ejecución por OF Construcción.", "facts": [["Arquitectura", "OF Arquitectos"], ["Construcción", "OF Construcción"], ["Año", "2026"], ["Superficie", "250 m²"], ["Estado", "En construcción"], ["Imágenes", "Visualizaciones del proyecto"]], "gallery": [["carrere-editorial-8.webp", "Acceso principal"], ["carrere-editorial-3.webp", "Cocina"], ["carrere-editorial-5.webp", "Estar y comedor"], ["carrere-editorial-4.webp", "Escalera de caracol"], ["carrere-editorial-6.webp", "Patio y piscina"], ["carrere-editorial-9.webp", "Baño principal"], ["carrere-editorial-10.webp", "Vestidor"]], "next": "galicia", "nextTitle": "Casa en Galicia"}, "galicia": {"title": "Casa en Galicia", "headline": "Una pieza nueva junto a la piedra.", "place": "Piñeiro, Cerido, España", "type": "Vivienda / En desarrollo", "image": "galicia-editorial-0.webp", "alt": "Visualización nocturna de la intervención en la casa de Piñeiro, Cerido", "sub": "En desarrollo.", "text": "La casa se emplaza en un pequeño pueblo de ladera de cerro, a solo diez minutos de la playa. El proyecto interviene una antigua casa de piedra, organizada en un nivel de acceso que se vincula, mediante medios pisos, con los dormitorios hacia arriba y con un antiguo establo hacia abajo. La intervención rescata la lógica original de la casa, demoliendo agregados posteriores poco afortunados y reordenando sus espacios para responder a las necesidades de sus nuevos residentes. A esta estructura preexistente se suma un cuerpo nuevo, resuelto en madera laminada prefabricada, que alberga el estar, comedor y cocina. Un sistema de aberturas conecta este volumen con los distintos niveles de la casa antigua, tensionando espacialmente lo nuevo con lo existente. El hórreo del predio, elemento tradicional de la arquitectura rural gallega, se conserva e incorpora un nuevo uso dentro del conjunto.", "facts": [["Arquitectura", "OF Arquitectos"], ["Año", "2026"], ["Estado", "En desarrollo"], ["Imágenes", "Visualizaciones del proyecto"]], "gallery": [["galicia-editorial-1.webp", "Interior de la pieza nueva"]], "next": "pdr-cordillera", "nextTitle": "Parque del Recuerdo, Parque Cordillera"}, "pdr-cordillera": {"title": "Parque del Recuerdo, Parque Cordillera", "headline": "Un jardín bajo techo.", "place": "Puente Alto, Santiago", "type": "Oficinas / En desarrollo", "image": "pdr-cordillera-editorial-0.webp", "alt": "Visualización del patio interior arbolado del edificio de atención", "sub": "Edificio de atención a las familias.", "text": "Edificio de atención al cliente para Parque del Recuerdo en Parque Cordillera. Los espacios de espera y atención se organizan en torno a un patio interior arbolado, cubierto por una techumbre abovedada que deja pasar la luz.", "facts": [["Arquitectura", "OF Arquitectos"], ["Mandante", "Parque del Recuerdo"], ["Año", "2025"], ["Superficie", "442 m²"], ["Estado", "En desarrollo"], ["Imágenes", "Visualizaciones del proyecto"]], "gallery": [["pdr-cordillera-editorial-1.webp", "Sala de espera junto al patio"], ["pdr-cordillera-editorial-2.webp", "Patio interior"], ["pdr-cordillera-editorial-3.webp", "Recorrido entre los árboles"], ["pdr-cordillera-editorial-4.webp", "Espacio de atención"]], "next": "ana-luisa", "nextTitle": "Estudio Ana Luisa"}, "ana-luisa": {"title": "Estudio Ana Luisa", "headline": "Un pabellón de acero en el jardín.", "place": "Santiago", "type": "Estudio de música residencial / Obra construida", "image": "ana-luisa-editorial-0.webp", "alt": "Estudio Ana Luisa, volumen de acero corten abierto hacia el patio", "sub": "Un estudio de música residencial.", "text": "Pabellón independiente en el patio de una casa, destinado a estudio de música. Un volumen revestido en acero corten se apoya sobre una base vidriada que se abre completamente hacia el patio; al interior, el revestimiento de madera trabaja la acústica del recinto.", "facts": [["Arquitectura", "OF Arquitectos"], ["Año", "2023"], ["Superficie", "40 m²"], ["Estado", "Construido"], ["Fotografía", "Aryeh Kornfeld"]], "chapters": [["Abierto al patio.", "Las puertas de vidrio se pliegan y el estudio se integra al patio y al espejo de agua.", [["editorial-1", "El pabellón junto al muro de ladrillo."], ["editorial-4", "El estudio abierto hacia el patio."]]], ["Una ventana circular.", "Una ventana circular en la cara lateral enmarca el interior desde el patio y la piscina.", [["editorial-2", "La ventana circular."], ["editorial-3", "Vista desde la piscina."]]], ["Materia.", "El acero corten envejece con el tiempo y dialoga con el muro de ladrillo existente.", [["editorial-5", "Acero corten y ladrillo."], ["editorial-6", "Vista general del patio."]]]], "next": "raya", "nextTitle": "Oficinas Agencia Raya"}, "raya": {"title": "Oficinas Agencia Raya", "headline": "Una oficina para una agencia creativa.", "place": "Santiago", "type": "Oficinas / Obra construida", "image": "raya-editorial-0.webp", "alt": "Recepción de Agencia Raya con muro de costillas de madera", "sub": "Habilitación de oficinas.", "text": "Oficinas para la agencia Raya. Un muro de costillas de madera recorre la recepción y la sala de reuniones y se convierte en la imagen de la oficina; los espacios de trabajo se organizan en torno a módulos revestidos en madera.", "facts": [["Arquitectura", "OF Arquitectos"], ["Mandante", "Agencia Raya"], ["Año", "2018"], ["Superficie", "645 m²"], ["Estado", "Construido"]], "gallery": [["raya-editorial-1.webp", "Muro de costillas hacia la sala de reuniones"], ["raya-editorial-3.webp", "Circulación y estar"]], "next": "vspt", "nextTitle": "Oficinas Viña San Pedro Tarapacá"}, "vspt": {"title": "Oficinas Viña San Pedro Tarapacá", "headline": "Oficinas con el vino al centro.", "place": "Vitacura, Santiago", "type": "Oficinas / Obra construida", "image": "vspt-editorial-0.webp", "alt": "Sala de degustación de las oficinas VSPT", "sub": "Habilitación de oficinas corporativas.", "text": "Habilitación de las oficinas de Viña San Pedro Tarapacá. Una sala de degustación con mesa larga, iluminación suspendida y muros de madera recuperada se convierte en el centro social de la oficina; las áreas de trabajo se ordenan junto a un muro continuo de madera.", "facts": [["Arquitectura", "OF Arquitectos"], ["Mandante", "Viña San Pedro Tarapacá"], ["Año", "2014"], ["Superficie", "1.200 m²"], ["Estado", "Construido"], ["Fotografía", "Francisco Cepeda"]], "gallery": [["vspt-editorial-1.webp", "Mesa y copas suspendidas"], ["vspt-editorial-2.webp", "Muro de madera en la circulación"], ["vspt-editorial-3.webp", "Oficinas junto al muro de madera"], ["vspt-editorial-5.webp", "Área de trabajo abierta"]], "next": "andes-iron", "nextTitle": "Oficinas Andes Iron"}, "andes-iron": {"title": "Oficinas Andes Iron", "headline": "Invertir la planta de oficinas.", "place": "Nueva Las Condes, Santiago", "type": "Oficinas / Obra construida", "image": "andes-iron-editorial-0.webp", "alt": "Recepción de las oficinas Andes Iron con muro de acero corten", "sub": "Primer lugar en concurso privado.", "text": "Habilitación de 1.400 m² en el piso 19 del Edificio de Las Artes, en Nueva Las Condes, a partir de un concurso privado. Tradicionalmente, las oficinas de gerencia ocupan el perímetro y dejan las zonas de trabajo abiertas sin luz natural ni vistas, aunque son las que más gente reúnen. El proyecto invierte ese orden: los privados se ubican al centro y el perímetro queda libre para todos.", "facts": [["Arquitectura", "Álvaro Ramírez, Francisco Cepeda"], ["Colaboradores", "Nicolás Cabargas, Natalia Rodríguez Gallego"], ["Mandante", "Andes Iron SpA"], ["Concurso", "Primer lugar"], ["Año", "2012"], ["Superficie", "1.400 m²"], ["Construcción", "BMU"], ["Fotografía", "Marcos Mendizábal"]], "chapters": [["El perímetro para todos.", "Las zonas de trabajo abiertas ocupan el borde de la planta y reciben luz natural y vistas hacia la ciudad y la cordillera.", [["editorial-1", "Puestos de trabajo junto a la fachada."], ["editorial-5", "Área de trabajo abierta."]]], ["Privados al centro.", "Las oficinas y salas de reunión se agrupan al centro de la planta, en volúmenes de vidrio y madera que no bloquean la luz.", [["editorial-4", "Oficinas de vidrio y madera."], ["editorial-8", "Sala vidriada al centro de la planta."]]], ["Encuentro y vistas.", "Salas de reunión y espacios comunes aprovechan las esquinas y las vistas del edificio.", [["editorial-2", "Sala de trabajo con vistas."], ["editorial-3", "Mesa de reuniones."], ["editorial-6", "Comedor junto a la fachada."], ["editorial-7", "Sala de directorio."]]]], "next": "buin", "nextTitle": "Casa Buin"}});
Object.assign(englishProjects,{"udla-conce": {"title": "UDLA Concepción", "headline": "A park at the heart of the campus.", "place": "Campus El Boldal, Concepción", "type": "Education / In development", "image": "udla-conce-hero-rearframe-2026.webp", "video": "udla-conce.mp4", "poster": "udla-conce-poster.webp", "videoCaption": "Competition video.", "alt": "Visualisation of the UDLA Concepción campus", "sub": "Master plan. First prize in competition.", "text": "Master plan for the Universidad de las Américas El Boldal campus, first prize together with MSRAA in a competition held in late 2025 and awarded in 2026. The project treats the campus as a University Garden City: an open system structured by landscape, in which architecture forms active edges around an Inner Park that acts as the academic, social and environmental heart. It is developed in two phases.", "facts": [["Architecture", "MSRAA + OF Arquitectos"], ["Competition", "First prize, 2026"], ["Year", "2026"], ["Area", "7,500 m²"], ["Status", "In development"], ["Images", "Architectural visualisations"]], "chapters": [["Plazas and steps.", "The buildings separate to form public spaces: an entrance plaza, stepped seating and shaded courtyards that work as meeting places.", [["editorial-2", "Plaza and steps between buildings."], ["editorial-3", "Entrance courtyard beneath the volumes."]]], ["Urban front.", "Facing the avenue, the complex presents a continuous façade with a transparent base and screens on the upper levels.", [["editorial-0", "The campus at dusk."], ["editorial-1", "Avenue façade."]]], ["Interiors.", "Auditorium and interior circulation continue the timber and metal materiality of the exterior.", [["editorial-4", "Interior circulation."], ["editorial-5", "Auditorium."]]]], "next": "udla-provi", "nextTitle": "UDLA Providencia"}, "udla-provi": {"title": "UDLA Providencia", "headline": "The courtyard, stacked.", "place": "Providencia, Santiago", "type": "Education / In development", "image": "udla-provi-editorial-0.webp", "alt": "Visualisation of the new UDLA Providencia building from the street", "video": "udla-provi.mp4", "poster": "udla-provi-poster.webp", "videoCaption": "Competition video.", "sub": "New campus. First prize in competition.", "text": "New Universidad de las Américas building in Providencia, first prize together with MSRAA in a competition held in late 2025 and awarded in 2026. The project takes the principles with which Germán Bannen shaped the district —pedestrian continuity, human scale, green space and mixed uses— and applies them to a tall building: the city does not stop at the property line, it continues inside the block.", "facts": [["Architecture", "MSRAA + OF Arquitectos"], ["Competition", "First prize, 2026"], ["Year", "2026"], ["Area", "7,500 m²"], ["Status", "In development"], ["Images", "Competition visualisations"]], "chapters": [["An urban platform.", "The first level is raised to form a platform that organises movement, allows pedestrians to pass through and extends public space into the building.", [["editorial-1", "The building from the street."], ["editorial-2", "Corner and entrance."]]], ["Raised courtyards.", "In the manor houses of central Chile, courtyards organise the programme and regulate climate. Here they are stacked vertically: voids and raised courtyards for academic encounters, with visual continuity and cross ventilation.", [["editorial-3", "Meeting space overlooking the Andes."], ["editorial-4", "Raised courtyard."]]], ["Open to the community.", "The most public uses —a 400-seat auditorium, an exhibition space and community clinics— sit on the lower levels and can operate independently of the university.", [["editorial-5", "Auditorium."], ["editorial-6", "Exhibition space."], ["editorial-7", "Main façade."]]]], "next": "cla", "nextTitle": "Colegio Los Andes"}, "cla": {"title": "Colegio Los Andes", "headline": "A civic courtyard for the school.", "place": "Santiago", "type": "Education / Competition", "image": "cla-editorial-0.webp", "alt": "Visualisation of the new Colegio Los Andes entrance building", "sub": "Master plan. Second prize in competition.", "text": "Master plan for Colegio Los Andes, a girls’ school founded in 1967, on a plateau site between San Damián and Las Hualtatas streets. The project reorganises the school’s access and courtyards: a new concrete façade with a skin of prefabricated timber screens regulates the climate of the grounds, a civic courtyard becomes the school’s new centre beside the existing chapel, and a new building —Edificio L— brings together the dining hall, auditorium and library. The kindergarten moves into its own pavilion.", "facts": [["Architecture", "OF + TNG"], ["Competition", "Second prize, 2024"], ["Year", "2024"], ["Status", "Design stage"], ["Images", "Competition visualisations"]], "chapters": [["The civic courtyard.", "A civic courtyard organises the complex beside the existing chapel, with a concrete structure that frames the passage between buildings.", [["editorial-3", "The civic courtyard beside the classroom buildings."], ["editorial-1", "The chapel courtyard."]]], ["Kindergarten and sport.", "The kindergarten moves into its own pavilion with rooms opening onto the play yard, and the complex adds a new sports building beside the running track.", [["editorial-2", "Kindergarten common room."], ["editorial-4", "The sports building beside the running track."]]]], "next": "cdv", "nextTitle": "Curaco de Vélez"}, "cdv": {"title": "Curaco de Vélez", "headline": "A great timber poncho.", "place": "Curaco de Vélez, Chiloé", "type": "Public building / Competition", "image": "cdv-editorial-0.webp", "alt": "Night visualisation of the Curaco de Vélez municipal building", "sub": "Municipal building. Public competition.", "text": "New municipal building for Curaco de Vélez, on a 75 by 40 m site facing the town’s Plaza Central in Chiloé. The project proposes one great interior, an \u201curban lock\u201d: a glazed nave runs through the building and links its programmes, sheltered by a timber structure inspired by the Williche poncho. One of the two naves is translucent, a glass greenhouse that houses the auditorium and craft fair on the ground floor, with the mayor’s office and council chamber hanging from the upper level. Laminated timber, Aluzinc steel and glass articulate the structure and façade.", "facts": [["Architecture", "OF Arquitectos"], ["Competition", "2024"], ["Year", "2024"], ["Site area", "75 x 40 m"], ["Status", "Design stage"], ["Images", "Competition visualisations"]], "gallery": [["cdv-editorial-1.webp", "The building in its setting, facing the town’s streets."]], "next": "numu", "nextTitle": "NUMU"}, "numu": {"title": "NUMU", "headline": "The cabinet of curiosities.", "place": "Parque Bicentenario, Vitacura", "type": "Culture / Competition", "image": "numu-editorial-0.webp", "alt": "Visualisation of the entrance hall of the New Museum of Santiago (NUMU)", "sub": "New Museum of Santiago. Public competition.", "text": "Entry for the New Museum of Santiago (NUMU) competition, beside Parque Bicentenario in Vitacura, in association with Elton Léniz and MCRJAG. The building presents itself as a silent, monochromatic volume wrapped in a screen that lets light through and allows the Park to enter a vertical entrance courtyard before becoming one continuous white-concrete hall. Exhibition rooms float above this hall, joined by a bridge and by a great stair that works as a grandstand connecting down to street level. A circulation core leads to the galleries, the auditorium, a circular basement courtyard and a rooftop sculpture terrace overlooking the Park and the San Cristóbal hill.", "facts": [["Architecture", "OF + Elton Léniz + MCRJAG"], ["Competition", "2020"], ["Year", "2020"], ["Status", "Design stage"], ["Images", "Competition visualisations"]], "gallery": [["numu-editorial-1.webp", "The grandstand stair and the bridge over the hall."], ["numu-editorial-2.webp", "Exhibition room and view towards the planted terrace."]], "next": "las-salinas", "nextTitle": "Las Salinas"}, "las-salinas": {"title": "Las Salinas", "headline": "Five volumes over the coastline.", "place": "Viña del Mar, Chile", "type": "Collective housing / In development", "image": "las-salinas-editorial-0.webp", "alt": "Visualisation of the Las Salinas project from the avenue, Viña del Mar", "sub": "One of the sites within the Barrio Las Salinas master plan, in collaboration with TNG.", "text": "A collective housing and ground-floor retail proposal for one of the sites within the Barrio Las Salinas master plan in Viña del Mar, a 16-hectare plan by TNG for Inmobiliaria Las Salinas (Empresas COPEC). OF collaborates with TNG on the design of this site. The programme sits on a continuous street-facing commercial base, above which five volumes of stepped height rise, wrapped in a vertical louvre skin that controls solar gain and unifies the ensemble.", "facts": [["Architecture", "OF + TNG"], ["Master plan", "Barrio Las Salinas, TNG"], ["Area", "95,000 sqm"], ["Location", "Viña del Mar"], ["Year", "2026"], ["Status", "Design stage"], ["Images", "Project visualisation"]], "next": "guadal-mixto", "nextTitle": "Casona Guadal"}, "guadal-mixto": {"title": "Casona Guadal", "headline": "Three volumes facing the plaza.", "place": "Puerto Guadal, Aysén", "type": "Collective housing / In development", "image": "guadal-mixto-editorial-0.webp", "alt": "Visualisation of Casona Guadal, west facade", "sub": "A mixed-use building in a low-rise village.", "text": "A three-storey building on a corner facing the plaza of Puerto Guadal. The street level holds commercial units, including a neighbourhood pharmacy; the upper floors contain eight rental apartments. To introduce this scale into a village of two-storey houses, the volume is split into three bodies that read as separate buildings.", "facts": [["Architecture", "Francisco Cepeda + Juan José Mena"], ["Year", "2026"], ["Area", "600 m²"], ["Programme", "Commercial units and eight apartments"], ["Status", "In development"], ["Images", "Architectural visualisations"]], "chapters": [["The settlers’ logic.", "Aysén’s settlers did not build a single house but a set of pieces: the house, the fire kitchen, the shed. The project follows that logic. The three bodies share a simple volume, pitched roof and timber cladding, and differ in the pattern of their boards: vertical, horizontal and diagonal.", [["editorial-1", "View from the plaza."], ["editorial-3", "West facade."], ["editorial-7", "View of the ensemble from the church."]]], ["An extension of the pavement.", "The retail level continues the pavement facing the plaza. A long canopy unifies the frontage and shelters from the rain; the pharmacy occupies the north volume and the café the corner.", [["editorial-4", "Shops and canopy."], ["editorial-6", "Access walkway to the apartments."]]], ["Morning and afternoon light.", "A steel walkway on the east side gives access to the apartments and keeps the street façade clean. Every unit receives morning and afternoon light and has cross ventilation; the roof creates double heights and lofts.", [["editorial-2", "Apartment interior."], ["editorial-5", "Inhabited section."]]]], "next": "carrere", "nextTitle": "Casa Carrere"}, "carrere": {"title": "Casa Carrere", "headline": "A house open to the garden.", "place": "Vitacura, Santiago", "type": "Private house / Under construction", "image": "carrere-editorial-0.webp", "alt": "Night visualisation of Casa Carrere from the garden", "sub": "In progress.", "text": "Renovation of a house in Vitacura. The ground floor opens to the garden through a covered terrace and large windows; inside, the kitchen, living room and a red spiral stair organise the shared spaces. Construction is being carried out by OF Construcción.", "facts": [["Architecture", "OF Arquitectos"], ["Contractor", "OF Construcción"], ["Year", "2026"], ["Area", "250 m²"], ["Status", "Under construction"], ["Images", "Architectural visualisations"]], "gallery": [["carrere-editorial-8.webp", "Main entrance"], ["carrere-editorial-3.webp", "Kitchen"], ["carrere-editorial-5.webp", "Living and dining"], ["carrere-editorial-4.webp", "Spiral stair"], ["carrere-editorial-6.webp", "Patio and pool"], ["carrere-editorial-9.webp", "Main bathroom"], ["carrere-editorial-10.webp", "Walk-in closet"]], "next": "galicia", "nextTitle": "Casa en Galicia"}, "galicia": {"title": "Casa en Galicia", "headline": "A new piece beside the stone.", "place": "Piñeiro, Cerido, Spain", "type": "Private house / In development", "image": "galicia-editorial-0.webp", "alt": "Night visualisation of the intervention at the Piñeiro house, Cerido", "sub": "In development.", "text": "The house sits in a small hillside village, ten minutes from the beach. The project intervenes in an old stone house, organised around an entry level linked by half-flights to the bedrooms above and an old stable below. The intervention recovers the house's original logic, demolishing unfortunate later additions and reorganising its spaces to suit its new residents. A new volume, built in prefabricated laminated timber, is added to this existing structure and houses the living room, dining room and kitchen. A system of openings connects this volume to the different levels of the old house, creating spatial tension between old and new. The horreo on the site, a traditional element of rural Galician architecture, is preserved and given a new use within the ensemble.", "facts": [["Architecture", "OF Arquitectos"], ["Year", "2026"], ["Status", "In development"], ["Images", "Architectural visualisations"]], "gallery": [["galicia-editorial-1.webp", "Interior of the new piece"]], "next": "pdr-cordillera", "nextTitle": "Parque del Recuerdo, Parque Cordillera"}, "pdr-cordillera": {"title": "Parque del Recuerdo, Parque Cordillera", "headline": "A garden under a roof.", "place": "Puente Alto, Santiago", "type": "Offices / In development", "image": "pdr-cordillera-editorial-0.webp", "alt": "Visualisation of the tree-planted inner courtyard of the visitor building", "sub": "A building for receiving families.", "text": "Visitor services building for Parque del Recuerdo at Parque Cordillera. Waiting and service areas are organised around a planted inner courtyard, covered by a vaulted roof that lets daylight in.", "facts": [["Architecture", "OF Arquitectos"], ["Client", "Parque del Recuerdo"], ["Year", "2025"], ["Area", "442 m²"], ["Status", "In development"], ["Images", "Architectural visualisations"]], "gallery": [["pdr-cordillera-editorial-1.webp", "Waiting area by the courtyard"], ["pdr-cordillera-editorial-2.webp", "Inner courtyard"], ["pdr-cordillera-editorial-3.webp", "Route among the trees"], ["pdr-cordillera-editorial-4.webp", "Service area"]], "next": "ana-luisa", "nextTitle": "Estudio Ana Luisa"}, "ana-luisa": {"title": "Estudio Ana Luisa", "headline": "A steel pavilion in the garden.", "place": "Santiago", "type": "Residential music studio / Built", "image": "ana-luisa-editorial-0.webp", "alt": "Estudio Ana Luisa, weathering-steel volume opening to the courtyard", "sub": "A residential music studio.", "text": "A freestanding pavilion in the courtyard of a house, used as a music studio. A weathering-steel volume rests on a glazed base that opens fully to the courtyard; inside, timber lining shapes the acoustics of the room.", "facts": [["Architecture", "OF Arquitectos"], ["Year", "2023"], ["Area", "40 m²"], ["Status", "Built"], ["Photography", "Aryeh Kornfeld"]], "chapters": [["Open to the courtyard.", "The glass doors fold back and the studio becomes part of the courtyard and the water.", [["editorial-1", "The pavilion beside the brick wall."], ["editorial-4", "The studio open to the courtyard."]]], ["A round window.", "A circular window on the side frames the interior from the courtyard and pool.", [["editorial-2", "The round window."], ["editorial-3", "View from the pool."]]], ["Material.", "Weathering steel ages over time and responds to the existing brick wall.", [["editorial-5", "Weathering steel and brick."], ["editorial-6", "Overall view of the courtyard."]]]], "next": "raya", "nextTitle": "Agencia Raya offices"}, "raya": {"title": "Agencia Raya offices", "headline": "An office for a creative agency.", "place": "Santiago", "type": "Offices / Built", "image": "raya-editorial-0.webp", "alt": "Agencia Raya reception with timber rib wall", "sub": "Office fit-out.", "text": "Offices for the Raya agency. A wall of timber ribs runs along the reception and meeting room and becomes the office’s identity; workspaces are organised around timber-clad modules.", "facts": [["Architecture", "OF Arquitectos"], ["Client", "Agencia Raya"], ["Year", "2018"], ["Area", "645 m²"], ["Status", "Built"]], "gallery": [["raya-editorial-1.webp", "Rib wall towards the meeting room"], ["raya-editorial-3.webp", "Circulation and lounge"]], "next": "vspt", "nextTitle": "Viña San Pedro Tarapacá offices"}, "vspt": {"title": "Viña San Pedro Tarapacá offices", "headline": "Offices with wine at the centre.", "place": "Vitacura, Santiago", "type": "Offices / Built", "image": "vspt-editorial-0.webp", "alt": "Tasting room at the VSPT offices", "sub": "Corporate office fit-out.", "text": "Fit-out of the Viña San Pedro Tarapacá offices. A tasting room with a long table, suspended lighting and reclaimed-timber walls becomes the social heart of the office; work areas are arranged along a continuous timber wall.", "facts": [["Architecture", "OF Arquitectos"], ["Client", "Viña San Pedro Tarapacá"], ["Year", "2014"], ["Area", "1,200 m²"], ["Status", "Built"], ["Photography", "Francisco Cepeda"]], "gallery": [["vspt-editorial-1.webp", "Table and suspended glasses"], ["vspt-editorial-2.webp", "Timber wall along the corridor"], ["vspt-editorial-3.webp", "Offices beside the timber wall"], ["vspt-editorial-5.webp", "Open work area"]], "next": "andes-iron", "nextTitle": "Andes Iron offices"}, "andes-iron": {"title": "Andes Iron offices", "headline": "Inverting the office floor.", "place": "Nueva Las Condes, Santiago", "type": "Offices / Built", "image": "andes-iron-editorial-0.webp", "alt": "Andes Iron reception with weathering-steel wall", "sub": "First prize in a private competition.", "text": "Fit-out of 1,400 m² on the 19th floor of the Edificio de Las Artes in Nueva Las Condes, following a private competition. Traditionally, executive offices take the perimeter and leave open work areas without daylight or views, even though they hold most people. The project reverses that order: private offices sit at the centre and the perimeter is freed for everyone.", "facts": [["Architecture", "Álvaro Ramírez, Francisco Cepeda"], ["Collaborators", "Nicolás Cabargas, Natalia Rodríguez Gallego"], ["Client", "Andes Iron SpA"], ["Competition", "First prize"], ["Year", "2012"], ["Area", "1,400 m²"], ["Contractor", "BMU"], ["Photography", "Marcos Mendizábal"]], "chapters": [["A perimeter for everyone.", "Open work areas occupy the edge of the floor and receive daylight and views towards the city and the Andes.", [["editorial-1", "Workstations along the façade."], ["editorial-5", "Open work area."]]], ["Private offices at the centre.", "Offices and meeting rooms are grouped at the centre of the floor in glass and timber volumes that do not block the light.", [["editorial-4", "Glass and timber offices."], ["editorial-8", "Glazed room at the centre of the floor."]]], ["Meeting and views.", "Meeting rooms and shared spaces take advantage of the building’s corners and views.", [["editorial-2", "Work room with views."], ["editorial-3", "Meeting table."], ["editorial-6", "Dining area by the façade."], ["editorial-7", "Boardroom."]]]], "next": "buin", "nextTitle": "Casa Buin"}});
