projects.vspt.text = 'La habilitación propone un espacio de trabajo compartido para Viña San Pedro Tarapacá. El anteproyecto combina puestos abiertos, salas de reunión flexibles y lugares para encuentros informales. La cafetería se concibe también como ámbito de intercambio y trabajo; la madera da continuidad e identidad a las áreas comunes.';
englishProjects.vspt.text = 'The fit-out proposes shared workspaces for Viña San Pedro Tarapacá. The design combines open workstations, flexible meeting rooms and places for informal encounters. The café is also conceived as a setting for exchange and work, while timber gives the common areas a consistent identity.';
projects['pdr-cordillera'].text = 'La propuesta para las oficinas de atención de Parque Cordillera reúne la espera interior y exterior en un solo recorrido. Un jardín de espera aprovecha la vegetación existente y orienta el paso hacia las áreas de atención, cajas y autoatención. El proyecto contempla una implementación prefabricada para reducir los tiempos de obra.';
englishProjects['pdr-cordillera'].text = 'The proposal for Parque Cordillera’s visitor services brings indoor and outdoor waiting areas into one sequence. A waiting garden makes use of existing planting and guides visitors towards the service desks, payment counters and self-service area. The scheme considers prefabrication to shorten on-site work.';
projects['ana-luisa'].text = 'Pabellón independiente en el patio de una casa, destinado a estudio de música. Un volumen metálico de tono óxido se apoya sobre una base vidriada que se abre hacia el patio; el interior está revestido en madera.';
englishProjects['ana-luisa'].text = 'A freestanding pavilion in the courtyard of a house, used as a music studio. A rust-toned metal volume rests on a glazed base that opens towards the courtyard; the interior is lined in timber.';
projects['ana-luisa'].chapters[2][1] = 'El revestimiento metálico de tono óxido dialoga con el ladrillo del muro existente. La base vidriada mantiene una relación directa entre el estudio y el patio.';
projects['ana-luisa'].chapters[2][2][0][1] = 'Revestimiento metálico y ladrillo.';
englishProjects['ana-luisa'].chapters[2][1] = 'The rust-toned metal cladding relates to the existing brick wall. The glazed base keeps a direct connection between the studio and the courtyard.';
englishProjects['ana-luisa'].chapters[2][2][0][1] = 'Metal cladding and brick.';
